-- ════════════════════════════════════════════════════════════════════
--  GestiQ — Migration 093 : Seed des 50 SOPs « Claude Code / DevOps / IA »
--  Date : 2026-08-31
--
--  Source : bibliothèque de procédures internes Next Gital (export Notion).
--  Généré par : scripts/generate-sops-claude-code.mjs — NE PAS ÉDITER À LA MAIN.
--  Insère uniquement pour les tenants disposant déjà du catalogue SOP
--  Next Gital (au moins un slug ng-%). Idempotent (WHERE NOT EXISTS).
--
--  Conformité ARCHITECTURE_TENANT.md :
--    - tenant_id NOT NULL, contrôle d'existence par (tenant_id, slug)
--    - RLS déjà actif sur public.sops (migration 025)
--    - Aucune modification de structure
--    - Aucun secret réel (clés API, mots de passe, clés SSH) : placeholders uniquement
-- ════════════════════════════════════════════════════════════════════

BEGIN;

-- ── ng-dev-git-commandes (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-git-commandes',
  'Commandes Git essentielles — le quotidien du développeur',
  'Les commandes Git à connaître par cœur, l''ordre à respecter à chaque session, comment revenir en arrière et les 4 actions interdites sans validation.',
  'dev',
  '["Git","GitHub","Développeur","Quotidien"]'::jsonb,
  'Next Gital',
  4,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Pour qui","text":"Tout développeur ou stagiaire Next Gital qui touche à un dépôt Git."},{"type":"callout","variant":"tip","title":"Objectif","text":"Ne jamais perdre de travail, ne jamais écraser celui d'un collègue, ne jamais casser la production."},{"type":"callout","variant":"danger","title":"Règle absolue","text":"Ne jamais exécuter automatiquement : git push · git commit · un déploiement · une modification de base de données. Toujours demander une validation avant ces 4 actions."},{"type":"heading","text":"1. Les commandes de base — à utiliser chaque jour"},{"type":"table","table":{"headers":["Commande","Ce qu'elle fait"],"rows":[["git status","Affiche l'état actuel du projet local"],["git pull","Récupère les dernières modifications depuis GitHub"],["git add .","Prépare toutes les modifications"],["git commit -m \"message\"","Enregistre les modifications localement"],["git push","Envoie les modifications vers GitHub"]]}},{"type":"heading","text":"2. L'ordre à respecter à chaque fois"},{"type":"code","text":"git pull              # Récupérer les dernières modifications\ngit status            # Voir ce qui a changé\ngit add .             # Préparer les fichiers\ngit commit -m \"...\"   # Enregistrer localement\ngit push              # Envoyer vers GitHub"},{"type":"callout","variant":"warning","title":"Toujours commencer par git pull","text":"Si on oublie le pull, on travaille sur une version obsolète et on crée des conflits inutiles."},{"type":"heading","text":"3. Revenir en arrière"},{"type":"table","table":{"headers":["Commande","Ce qu'elle fait"],"rows":[["git log","Voir l'historique des commits"],["git diff","Voir les modifications avant le commit"],["git stash","Sauvegarder temporairement les modifications"],["git stash pop","Restaurer les modifications sauvegardées"],["git reset --hard HEAD","⚠️ Revenir au dernier commit (destructif)"]]}},{"type":"callout","variant":"danger","title":"git reset --hard","text":"Cette commande supprime définitivement toutes les modifications non enregistrées. Faire un `git stash` avant, systématiquement."},{"type":"heading","text":"Checklist de fin de session"},{"type":"checklist","items":["git status → working tree clean","Aucun fichier sensible (.env, clés, dumps) dans le commit","Message de commit explicite (pas « update » ni « fix »)","Validation obtenue avant le push"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-git-commandes');

-- ── ng-dev-git-branch (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-git-branch',
  'Développer une fonctionnalité sur une branche Git',
  'Créer une branche dédiée, développer, tester, fusionner dans main puis publier — sans jamais impacter la version officielle du projet.',
  'dev',
  '["Git","Branche","Feature","Workflow"]'::jsonb,
  'Next Gital',
  5,
  false,
  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Développer une nouvelle fonctionnalité sans impacter la version officielle du projet."},{"type":"callout","variant":"danger","title":"Interdit sans validation","text":"git push · déploiement en production · modification de base de données."},{"type":"heading","text":"Étapes — dans l'ordre"},{"type":"heading2","text":"1. Mettre à jour le projet"},{"type":"code","text":"git checkout main\ngit pull"},{"type":"heading2","text":"2. Créer la branche de travail"},{"type":"code","text":"git checkout -b feature/nom-fonctionnalite\n\n# Exemple\ngit checkout -b feature/module-expedition"},{"type":"callout","variant":"info","title":"Nommage","text":"Toujours `feature/` + un nom court en minuscules avec des tirets. Ex : feature/module-expedition, feature/export-pdf."},{"type":"heading2","text":"3. Développer puis vérifier"},{"type":"code","text":"git status"},{"type":"heading2","text":"4. Sauvegarder les modifications"},{"type":"code","text":"git add .\ngit commit -m \"Ajout du module d'expédition\""},{"type":"heading2","text":"5. Tester avant toute intégration"},{"type":"list","items":["Vérifier que l'application démarre correctement","Contrôler l'absence d'erreurs console et API","Valider les tests fonctionnels de la fonctionnalité"]},{"type":"heading2","text":"6. Intégrer dans la branche principale"},{"type":"code","text":"git checkout main\ngit pull\ngit merge feature/module-expedition"},{"type":"heading2","text":"7. Validation finale"},{"type":"checklist","items":["Le projet fonctionne après le merge","Aucun conflit restant","Conformité aux exigences du client"]},{"type":"heading2","text":"8. Publication sur GitHub — après validation uniquement"},{"type":"code","text":"git push"},{"type":"divider"},{"type":"heading","text":"Workflow résumé"},{"type":"code","text":"git checkout main\ngit pull\n\ngit checkout -b feature/nom-fonctionnalite\n# … développement …\ngit add .\ngit commit -m \"Description\"\n\ngit checkout main\ngit pull\ngit merge feature/nom-fonctionnalite\n\n# Après validation uniquement\ngit push"}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-git-branch');

-- ── ng-dev-git-synchronisation (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-git-synchronisation',
  'Vérifier la synchronisation Git — « je ne vois pas les dernières modifications »',
  'Interpréter la sortie de git status, savoir si le local est à jour avec GitHub, et débloquer un collègue qui ne voit pas les changements.',
  'dev',
  '["Git","Diagnostic","Synchronisation"]'::jsonb,
  'Next Gital',
  3,
  false,
  $sop$[{"type":"callout","variant":"info","title":"Quand utiliser cette SOP","text":"Un membre de l'équipe dit « je ne vois pas les dernières modifications » ou « le site n'a pas changé »."},{"type":"heading","text":"1. Vérifier l'état du dépôt"},{"type":"code","text":"git status"},{"type":"paragraph","text":"Résultat attendu :"},{"type":"code","text":"Your branch is up to date with 'origin/main'\nnothing to commit, working tree clean"},{"type":"paragraph","text":"Cela signifie que :"},{"type":"list","items":["Le projet local est synchronisé avec GitHub","Aucun fichier n'est en attente d'envoi","La version locale est identique à la branche main"]},{"type":"heading","text":"2. Si les modifications ne s'affichent toujours pas"},{"type":"numbered","items":["Vérifier que le développeur a bien poussé son travail sur main (git log origin/main --oneline -5)","Relancer les dépendances et le serveur : npm install puis npm run dev","Vider le cache du navigateur : Cmd + Shift + R (Mac) ou Ctrl + Shift + R (Windows)"]},{"type":"heading","text":"3. Cas particulier — un stash existe"},{"type":"callout","variant":"warning","title":"Ne pas supprimer un stash","text":"Un `stash@{0}` est conservé comme sauvegarde de sécurité. Ne jamais le supprimer avant vérification complète du travail en cours."},{"type":"code","text":"git stash list      # lister les sauvegardes\ngit stash show -p    # voir le contenu du dernier stash"},{"type":"heading","text":"Checklist"},{"type":"checklist","items":["git status → working tree clean","git log origin/main confirme la présence du commit attendu","npm install + npm run dev relancés","Cache navigateur vidé"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-git-synchronisation');

-- ── ng-dev-github-nouveau-projet (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-github-nouveau-projet',
  'Publier un nouveau projet sur GitHub',
  'Créer le dépôt, initialiser Git en local et pousser le projet en 6 commandes. Inclut le cas d''un dépôt déjà créé avec un README et l''authentification par token.',
  'dev',
  '["GitHub","Git","Nouveau projet","Initialisation"]'::jsonb,
  'Next Gital',
  3,
  false,
  $sop$[{"type":"heading","text":"Étape 1 — Créer le dépôt sur GitHub"},{"type":"numbered","items":["Aller sur github.com/new","Donner un nom au dépôt","Ne rien cocher (pas de README, pas de .gitignore)","Cliquer sur Create repository"]},{"type":"heading","text":"Étape 2 — Dans le terminal"},{"type":"code","text":"cd /chemin/vers/ton-projet\n\ngit init\ngit add .\ngit commit -m \"Initial commit\"\ngit branch -M main\ngit remote add origin https://github.com/USERNAME/NOM-REPO.git\ngit push -u origin main"},{"type":"callout","variant":"success","title":"Résultat","text":"6 commandes, projet en ligne."},{"type":"heading","text":"Cas particulier — dépôt déjà créé avec un README"},{"type":"code","text":"git pull origin main --allow-unrelated-histories\ngit push -u origin main"},{"type":"heading","text":"Problème de mot de passe"},{"type":"paragraph","text":"GitHub n'accepte plus les mots de passe : il faut un Personal Access Token."},{"type":"numbered","items":["GitHub → Settings → Developer settings","Personal access tokens → Tokens (classic) → Generate","Cocher le scope « repo »","Utiliser ce token comme mot de passe"]},{"type":"callout","variant":"danger","title":"Sécurité","text":"Ne jamais committer un token, une clé API ou un fichier .env. Vérifier le .gitignore AVANT le premier commit."}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-github-nouveau-projet');

-- ── ng-dev-lancer-projet-github-vscode (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-lancer-projet-github-vscode',
  'Lancer un projet depuis GitHub avec VS Code',
  'Prérequis à installer, clonage du dépôt, npm install, npm run dev, accès au localhost et résolution des 3 problèmes les plus fréquents.',
  'dev',
  '["VS Code","GitHub","Onboarding","Node.js","npm"]'::jsonb,
  'Next Gital',
  5,
  true,
  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Permettre à n'importe quel membre de l'équipe de télécharger et lancer un projet en local, sans erreurs."},{"type":"heading","text":"Prérequis — à installer avant de commencer"},{"type":"table","table":{"headers":["Outil","Lien","Vérification"],"rows":[["VS Code","https://code.visualstudio.com","L'application s'ouvre"],["Node.js (LTS)","https://nodejs.org","`node -v` et `npm -v` répondent"],["Git","https://git-scm.com/downloads","`git --version` répond"],["Compte GitHub","https://github.com/signup","Connexion OK"],["Accès au dépôt","Demander au responsable","Le dépôt est visible"]]}},{"type":"heading","text":"Étapes — dans l'ordre"},{"type":"heading2","text":"1. Cloner le projet"},{"type":"numbered","items":["Ouvrir VS Code","Cliquer sur « Clone Repository »","Coller le lien du dépôt GitHub","Choisir un dossier (ex : Desktop)","Cliquer sur Open après le téléchargement"]},{"type":"heading2","text":"2. Ouvrir le terminal"},{"type":"paragraph","text":"Menu : Terminal → New Terminal, ou raccourci Ctrl + `"},{"type":"heading2","text":"3. Installer les dépendances"},{"type":"code","text":"npm install"},{"type":"callout","variant":"warning","title":"Ne pas couper le processus","text":"Attendre la fin complète de l'installation, même si cela prend plusieurs minutes."},{"type":"heading2","text":"4. Lancer le projet"},{"type":"code","text":"npm run dev"},{"type":"heading2","text":"5. Accéder au projet"},{"type":"paragraph","text":"Un lien apparaît dans le terminal, par exemple http://localhost:8080 — cliquer dessus ou l'ouvrir dans le navigateur."},{"type":"heading2","text":"6. Avant chaque session de travail"},{"type":"code","text":"git pull"},{"type":"divider"},{"type":"heading","text":"Problèmes fréquents"},{"type":"table","table":{"headers":["Symptôme","Cause","Solution"],"rows":[["Port 8080 is in use","Un autre projet tourne déjà","Utiliser le nouveau lien proposé automatiquement"],["Erreur npm install","Node.js absent ou pas de connexion","Vérifier `node -v` et la connexion Internet"],["Le projet ne s'ouvre pas","Serveur non lancé","Vérifier que `npm run dev` tourne toujours"]]}},{"type":"callout","variant":"danger","title":"Règle d'équipe","text":"Si quelqu'un ne fait pas `git pull`, il travaille sur une version obsolète. Si une question est déjà répondue dans cette SOP, c'est qu'elle n'a pas été lue."}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-lancer-projet-github-vscode');

-- ── ng-dev-dokploy-deploiement (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-dokploy-deploiement',
  'Déployer un projet GitHub sur Dokploy',
  'Créer le projet et le service, connecter GitHub, configurer le build (Nixpacks / Static / Dockerfile), le domaine, le SSL Let''s Encrypt et l''auto-deploy à chaque push.',
  'dev',
  '["Dokploy","Déploiement","VPS","CI/CD","DNS"]'::jsonb,
  'Next Gital',
  7,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Contexte","text":"Dokploy tourne sur le VPS Hostinger Next Gital. Interface : http://<IP_VPS>:3000."},{"type":"heading","text":"Étapes — dans l'ordre"},{"type":"heading2","text":"1. Créer un nouveau projet"},{"type":"numbered","items":["Cliquer sur + Create Project","Donner un nom (ex : fdx-renovation)","Cliquer sur Create"]},{"type":"heading2","text":"2. Ajouter un service"},{"type":"numbered","items":["Ouvrir le projet créé","Cliquer sur + Add Service","Choisir Application"]},{"type":"heading2","text":"3. Connecter GitHub"},{"type":"numbered","items":["Dans Source, choisir GitHub","Cliquer sur Connect GitHub (première fois → autoriser Dokploy sur le compte)","Sélectionner le dépôt","Branch : main"]},{"type":"callout","variant":"info","title":"Installation de l'app GitHub","text":"GitHub demande « Install & Authorize » : choisir All repositories ou Only select repositories, puis valider. La redirection se fait vers http://<IP_VPS>:3000/api/providers/github/setup."},{"type":"heading2","text":"4. Configurer le build"},{"type":"table","table":{"headers":["Champ","Valeur"],"rows":[["Build Type","Nixpacks (auto-détecte Vite/Node) · Static pour un site HTML pur · Dockerfile si présent"],["Publish Directory","/ ou dist selon le projet"],["Port","80 pour un site statique, 3000/4000 pour une app Node"],["Build command","npm run build"],["Start command","npx serve dist -p 3000 (site statique buildé)"]]}},{"type":"callout","variant":"tip","title":"Site HTML/CSS/JS pur","text":"Créer un Dockerfile nginx:alpine à la racine : image de base nginx:alpine, copie des fichiers vers /usr/share/nginx/html, EXPOSE 80. Ajouter un .dockerignore excluant node_modules, .git, .claude, *.md."},{"type":"heading2","text":"5. Pointer le domaine vers le VPS"},{"type":"paragraph","text":"Chez le registrar du domaine, dans la zone DNS :"},{"type":"table","table":{"headers":["Type","Nom","Valeur","TTL"],"rows":[["A","@","<IP_DU_VPS>","300"],["A","www","<IP_DU_VPS>","300"]]}},{"type":"paragraph","text":"Vérifier la propagation sur dnschecker.org (5 min à 24 h selon le registrar)."},{"type":"heading2","text":"6. Configurer le domaine dans Dokploy"},{"type":"numbered","items":["Onglet Domains → Add Domain","Host = le domaine · Port = celui du service","Activer HTTPS + Let's Encrypt","Cliquer sur Update / Create"]},{"type":"heading2","text":"7. Déployer"},{"type":"numbered","items":["Cliquer sur Deploy","Surveiller les logs en temps réel","Vert = déployé"]},{"type":"heading2","text":"8. Activer l'auto-deploy (CI/CD)"},{"type":"numbered","items":["Onglet General du service","Activer Autodeploy","Trigger Type = On Push · Branch = main"]},{"type":"callout","variant":"success","title":"Résultat","text":"Dokploy redéploie automatiquement à chaque `git push` sur main."},{"type":"divider"},{"type":"heading","text":"Checklist de déploiement"},{"type":"checklist","items":["Build vert dans les logs Dokploy","Domaine racine + www répondent en HTTPS","Certificat Let's Encrypt actif (cadenas 🔒)","Variables d'environnement renseignées dans l'onglet Environment","Autodeploy activé sur main"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-dokploy-deploiement');

-- ── ng-dev-dokploy-mdp-postgres (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-dokploy-mdp-postgres',
  'Changer le mot de passe PostgreSQL en production (Dokploy)',
  'Sécuriser une base exposée : modifier le mot de passe via le terminal du conteneur, répercuter la valeur dans les variables d''environnement de l''API, redéployer et vérifier les logs.',
  'dev',
  '["PostgreSQL","Dokploy","Sécurité","Production","Base de données"]'::jsonb,
  'Next Gital',
  5,
  false,
  $sop$[{"type":"callout","variant":"warning","title":"Contexte","text":"Quand l'External Port de la base ne peut pas être modifié dans Dokploy, un mot de passe fort réduit fortement le risque d'accès non autorisé. C'est l'action prioritaire."},{"type":"callout","variant":"danger","title":"Avant de commencer","text":"Prévenir l'équipe : l'API sera indisponible quelques minutes le temps du redéploiement. Faire un backup (pg_dump) avant toute intervention."},{"type":"heading","text":"Étape 1 — Modifier le mot de passe PostgreSQL"},{"type":"numbered","items":["Dans Dokploy, ouvrir le service de base de données → bouton Open Terminal","Se connecter à PostgreSQL"]},{"type":"code","text":"psql -U postgres -d <nom_base>"},{"type":"paragraph","text":"Le prompt affiche `<nom_base>=#`. Définir alors un mot de passe fort :"},{"type":"code","text":"ALTER USER postgres WITH PASSWORD '<NOUVEAU_MOT_DE_PASSE_FORT>';"},{"type":"callout","variant":"success","title":"Résultat attendu","text":"PostgreSQL affiche : ALTER ROLE"},{"type":"paragraph","text":"Quitter avec `\\q`."},{"type":"heading","text":"Étape 2 — Mettre à jour l'application API"},{"type":"numbered","items":["Ouvrir le service applicatif (pas le service base de données)","Onglet Environment","Rechercher la variable DB_PASSWORD","Remplacer par le nouveau mot de passe — exactement le même que celui défini dans PostgreSQL","Cliquer sur Save","Cliquer sur Redeploy (ou Reload)"]},{"type":"callout","variant":"warning","title":"Caractères spéciaux","text":"Si le mot de passe contient #, $, !, ou des espaces, l'entourer de guillemets : DB_PASSWORD=\"Xk9mP2#vL8nQ4wR\"."},{"type":"heading","text":"Étape 3 — Vérification"},{"type":"paragraph","text":"Ouvrir l'onglet Logs du service applicatif. On doit voir :"},{"type":"code","text":"[API] listening on http://0.0.0.0:4000"},{"type":"paragraph","text":"Et ne plus voir :"},{"type":"code","text":"[PG POOL ERROR] password authentication failed"},{"type":"heading","text":"Checklist"},{"type":"checklist","items":["Backup pg_dump réalisé avant intervention","ALTER ROLE confirmé dans psql","DB_PASSWORD mis à jour dans Environment","Service redéployé","Logs propres — API en écoute, aucune erreur d'authentification","Nouveau mot de passe stocké dans le gestionnaire de secrets (jamais dans Git)"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-dokploy-mdp-postgres');

-- ── ng-dev-feature-a-z (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-feature-a-z',
  'Développer une nouvelle fonctionnalité de A à Z (GestiQ)',
  'Les 14 étapes obligatoires, de la migration SQL au déploiement production, avec la règle d''or de l''ordre d''exécution et le tableau des erreurs fréquentes.',
  'dev',
  '["GestiQ","Migration","Backend","Frontend","Déploiement"]'::jsonb,
  'Next Gital',
  8,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Règle d'or","text":"Migration → Backend → API Client → UI → Tests → Commit → Push → Migration Production → Déploiement. Chaque nouvelle fonctionnalité suit exactement cet ordre. Si une étape est oubliée, consulter la section « Erreurs fréquentes »."},{"type":"heading","text":"Les 14 étapes"},{"type":"numbered","items":["Planification et analyse des besoins","Rédaction de la migration SQL (supabase/migrations/NNN_nom.sql)","Exécution de la migration en local","Création de la route Backend (server/routes/)","Redémarrage du serveur","Création ou mise à jour de l'API Client (src/lib/api.ts)","Création ou modification des pages React","Enregistrement des routes dans App.tsx et AppLayout.tsx","Vérification TypeScript (npx tsc --noEmit)","Tests locaux complets","Commit Git (éviter git add . sans vérification)","Push GitHub — uniquement après validation explicite","Exécution de la migration sur la production Dokploy","Déploiement de l'application en production"]},{"type":"heading","text":"Cheat sheet — commandes essentielles"},{"type":"code","text":"# Local\nnpm run dev\nnpx tsc --noEmit\nnpm run build\n\n# Migration locale\npsql -h localhost -p <port> -U <user> -d <base> -f supabase/migrations/NNN_nom.sql\n\n# Migration production (via SSH + Docker)\ncat supabase/migrations/NNN_nom.sql | ssh <cible> \\\n  \"docker exec -i <conteneur_pg> psql -U <user> -d <base> -v ON_ERROR_STOP=1\""},{"type":"heading","text":"Erreurs fréquentes"},{"type":"table","table":{"headers":["Erreur","Cause probable","Solution"],"rows":[["erreur 42703 — column does not exist","Migration non appliquée en production","Rejouer la migration sur la base prod"],["postgres is not permitted to log in","Rôle sans LOGIN","Utiliser le rôle applicatif de l'app"],["Port 8080 is already in use","Serveur déjà lancé","Utiliser le port proposé ou tuer le process"],["Erreur TypeScript au build","Types non mis à jour après la migration","Mettre à jour les interfaces + npx tsc --noEmit"],["Bouton sans effet","Route API non enregistrée","Vérifier server/routes + src/lib/api.ts"]]}},{"type":"heading","text":"Checklist avant push"},{"type":"checklist","items":["Migration testée en local, idempotente (IF NOT EXISTS / WHERE NOT EXISTS)","RLS et tenant_id conformes à ARCHITECTURE_TENANT.md","npx tsc --noEmit sans erreur","npm run build sans erreur","Fonctionnalité testée dans le navigateur","Aucune erreur console ni API","Validation obtenue avant git push"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-feature-a-z');

-- ── ng-dev-ssh-vps-hostinger (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-ssh-vps-hostinger',
  'Connecter Claude Code à un VPS Hostinger via SSH',
  'Générer une paire de clés ed25519, l''installer sur le VPS Hostinger, créer un alias ~/.ssh/config, tester la connexion et l''utiliser depuis Claude Code. Règles de sécurité incluses.',
  'dev',
  '["SSH","VPS","Hostinger","Claude Code","Sécurité"]'::jsonb,
  'Next Gital',
  6,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Durée","text":"15 minutes · Difficulté : facile."},{"type":"callout","variant":"tip","title":"Objectif","text":"Permettre à Claude Code d'exécuter des commandes en sécurité sur un VPS distant : diagnostiquer PostgreSQL, consulter les logs Docker, automatiser la maintenance, récupérer des dumps."},{"type":"callout","variant":"danger","title":"Jamais dans un document partagé","text":"Une clé privée SSH ne doit JAMAIS être collée dans une note, un ticket, un SOP ou un message. Elle reste uniquement dans ~/.ssh sur la machine."},{"type":"heading","text":"Étape 1 — Générer une paire de clés SSH sur le Mac"},{"type":"code","text":"ssh-keygen -t ed25519 -C \"<prenom>-vps-hostinger\" -f ~/.ssh/id_ed25519"},{"type":"paragraph","text":"Appuyer sur Entrée pour accepter le nom par défaut, puis saisir une passphrase (recommandé)."},{"type":"code","text":"ls -la ~/.ssh/id_ed25519*"},{"type":"paragraph","text":"Résultat attendu : la clé privée (id_ed25519, à ne JAMAIS partager) et la clé publique (id_ed25519.pub, à partager)."},{"type":"heading","text":"Étape 2 — Vérifier les permissions"},{"type":"callout","variant":"warning","title":"Obligatoire","text":"Sans ces permissions strictes, SSH refuse la connexion."},{"type":"code","text":"chmod 700 ~/.ssh\nchmod 600 ~/.ssh/id_ed25519\nchmod 644 ~/.ssh/id_ed25519.pub"},{"type":"heading","text":"Étape 3 — Copier la clé publique"},{"type":"code","text":"pbcopy < ~/.ssh/id_ed25519.pub"},{"type":"heading","text":"Étape 4 — Ajouter la clé publique au VPS"},{"type":"numbered","items":["Aller sur https://hpanel.hostinger.com/vps","Cliquer sur le VPS → menu latéral Security → SSH Keys","Cliquer sur Add SSH Key","Name : nom descriptif de la machine","Public Key : Cmd+V","Save, puis redémarrer le VPS ou attendre 30 secondes"]},{"type":"heading","text":"Étape 5 — Créer un alias dans ~/.ssh/config"},{"type":"code","text":"cat >> ~/.ssh/config << 'EOF'\n\nHost <ALIAS>\n    HostName <VPS_HOSTNAME>\n    User root\n    Port 22\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n    ServerAliveCountMax 3\nEOF\n\nchmod 600 ~/.ssh/config"},{"type":"heading","text":"Étape 6 — Tester la connexion"},{"type":"code","text":"ssh -o BatchMode=yes -o ConnectTimeout=8 <ALIAS> \"hostname && whoami && uptime\""},{"type":"callout","variant":"success","title":"Résultat attendu","text":"Le hostname du VPS, root, et l'uptime s'affichent → connexion SSH opérationnelle."},{"type":"heading","text":"Étape 7 — Utiliser depuis Claude Code"},{"type":"code","text":"ssh <ALIAS> \"docker ps\"\n\nssh <ALIAS> \"docker exec <CONTENEUR_PG> psql -U <DB_USER> -d <DB_NAME> -c 'SELECT COUNT(*) FROM <TABLE>;'\""},{"type":"divider"},{"type":"heading","text":"Règles de sécurité"},{"type":"table","table":{"headers":["Règle","Pourquoi"],"rows":[["Ne jamais partager ~/.ssh/id_ed25519","Contrôle total du VPS pour qui la détient"],["Toujours une passphrase sur la clé privée","Protection en cas de vol de la machine"],["Ne jamais committer ~/.ssh/*","Fuite définitive"],["Utiliser ed25519 (jamais RSA 1024)","Standard sécurisé moderne"],["Restrictions IP dans Hostinger si possible","Réduit la surface d'attaque"],["Rotation de la clé tous les 12 mois","Réduit le risque en cas de fuite non détectée"]]}},{"type":"heading","text":"Dépannage"},{"type":"table","table":{"headers":["Symptôme","Cause","Solution"],"rows":[["Permission denied (publickey)","Clé absente du VPS ou permissions incorrectes","Refaire les étapes 2 et 4"],["Connection timed out","Firewall ou mauvaise IP","Vérifier l'IP dans Hostinger Overview"],["Host key verification failed","L'IP du VPS a changé","ssh-keygen -R <VPS_HOSTNAME> puis reconnecter"],["Passphrase demandée à chaque commande","Pas de ssh-agent","ssh-add ~/.ssh/id_ed25519 (1 fois par session)"]]}}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-ssh-vps-hostinger');

-- ── ng-dev-intervention-serveur-env (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-intervention-serveur-env',
  'Intervenir sur un serveur en production à partir du .env du projet',
  'Cadre d''intervention pour Claude Code : lire les accès dans .env sans les exposer, diagnostiquer Docker / Nginx / Dokploy / base / SSL, corriger, tester et produire un rapport.',
  'dev',
  '["SSH","Docker","Dokploy","Production","Diagnostic"]'::jsonb,
  'Next Gital',
  5,
  false,
  $sop$[{"type":"callout","variant":"info","title":"Contexte","text":"Les accès serveur (SSH, clé privée, base) sont déjà présents dans le fichier .env du projet ou dans la plateforme d'hébergement."},{"type":"callout","variant":"danger","title":"Interdits absolus","text":"Ne jamais afficher, copier ou logger le contenu du .env. Ne jamais publier de secret dans Git. Ne pas modifier les clés SSH, mots de passe ou tokens existants sauf nécessité absolue."},{"type":"heading","text":"Ce qu'il faut vérifier — dans l'ordre"},{"type":"numbered","items":["Analyser le projet et identifier la cause exacte du problème","État des conteneurs Docker (docker ps, docker logs)","Logs de l'application","Logs Nginx / reverse proxy (Traefik)","Configuration Dokploy du service","Variables d'environnement du service","Connexion à la base de données","Ports utilisés","Domaine et certificat SSL","Permissions des fichiers","État du déploiement et des services"]},{"type":"heading","text":"Procédure de correction"},{"type":"numbered","items":["Identifier la cause racine (pas le symptôme)","Créer une sauvegarde des fichiers ou configurations concernés avant toute modification risquée","Appliquer la correction sans supprimer de données existantes","Redémarrer uniquement les services nécessaires","Tester en conditions réelles"]},{"type":"heading","text":"Tests de validation obligatoires"},{"type":"checklist","items":["Le site est accessible","L'API répond","La base de données répond correctement","Aucune erreur critique dans les logs","Le domaine et le HTTPS fonctionnent"]},{"type":"heading","text":"Rapport final attendu"},{"type":"list","items":["La cause exacte du problème","Les fichiers et configurations modifiés","Les commandes exécutées","Les services redémarrés","Les tests effectués et leur résultat","Les recommandations de sécurité ou de maintenance"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-intervention-serveur-env');

-- ── ng-dev-wordpress-ssh-claude (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-wordpress-ssh-claude',
  'Intervenir sur un site WordPress en production via SSH',
  'Cadre strict d''intervention sur un site WordPress hébergé : identifier le bon dossier, analyser avant de modifier, sauvegarder, corriger, tester chaque page et livrer un rapport.',
  'dev',
  '["WordPress","SSH","Hostinger","Production","Maintenance"]'::jsonb,
  'Next Gital',
  7,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Règle numéro 1 — un seul site","text":"Un compte d'hébergement contient souvent plusieurs sites. N'intervenir QUE sur le domaine désigné. Si le dossier ne correspond pas au domaine annoncé, ARRÊTER et demander confirmation."},{"type":"heading","text":"Étape 1 — Connexion SSH"},{"type":"code","text":"ssh -p <PORT> <UTILISATEUR>@<IP_HEBERGEMENT>"},{"type":"callout","variant":"warning","title":"Identifiants","text":"Les identifiants viennent du .env du projet ou du gestionnaire de secrets — jamais d'un autre projet, jamais collés dans un document partagé."},{"type":"heading","text":"Étape 2 — Vérifier qu'on est sur le bon site"},{"type":"numbered","items":["Localiser le dossier racine du domaine","Vérifier que wp-config.php appartient bien à ce domaine","Vérifier l'URL du site (wp option get siteurl)","Confirmer explicitement avant toute modification"]},{"type":"code","text":"wp option get siteurl\nwp option get home\nwp core version"},{"type":"heading","text":"Étape 3 — Analyser avant de modifier"},{"type":"list","items":["Identifier les erreurs (PHP, JavaScript, CSS, thème, extensions)","Vérifier les plugins et le thème actif","Contrôler les permaliens, le .htaccess, le SSL","Relever les liens cassés, images manquantes, erreurs 404 / 500","Mesurer les performances et le responsive"]},{"type":"callout","variant":"info","title":"Livrable intermédiaire","text":"Présenter un rapport d'analyse complet AVANT toute correction, et attendre l'autorisation."},{"type":"heading","text":"Étape 4 — Corriger"},{"type":"list","items":["Corriger uniquement les problèmes détectés","Ne désactiver un plugin que si c'est indispensable — et expliquer pourquoi","Ne supprimer aucune donnée importante","Sauvegarder avant chaque modification risquée","Si une correction crée une nouvelle erreur, la corriger immédiatement avant de continuer"]},{"type":"heading","text":"Étape 5 — Tester chaque page"},{"type":"checklist","items":["La page d'accueil","Toutes les pages publiées et les articles","Les formulaires, menus, boutons, images","Header et footer","Liens internes et externes","Pages de contact et pages légales"]},{"type":"heading","text":"Étape 6 — SEO, performance et sécurité"},{"type":"list","items":["SEO : robots.txt, sitemap.xml, meta title/description, canonical, Open Graph, Schema.org, breadcrumbs, redirections","Performance : cache, CSS, JavaScript, images, lazy loading, compression, Core Web Vitals","Sécurité : permissions, HTTPS, headers de sécurité, fichiers sensibles, comptes administrateurs, plugins vulnérables"]},{"type":"heading","text":"Validation finale"},{"type":"checklist","items":["La page d'accueil fonctionne","Toutes les pages répondent correctement","Aucun lien important n'est cassé","Aucun formulaire en erreur","Aucune erreur PHP ni JavaScript critique","Aucune erreur 404 ou 500 importante","Le SEO technique est valide","Le site est rapide et sécurisé"]},{"type":"heading","text":"Rapport final"},{"type":"list","items":["Tous les problèmes corrigés","Les fichiers modifiés","Les plugins modifiés","Les optimisations réalisées","Les tests effectués","Les problèmes restants éventuels"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-wordpress-ssh-claude');

-- ── ng-dev-wordpress-local-claude (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-wordpress-local-claude',
  'Développer un site WordPress avec Claude Code (Local by Flywheel)',
  'Du brief design au thème sur-mesure : bonnes pratiques Claude Code, structure d''un bon prompt, création du site local, développement du thème, mise en ligne et checklist de livraison.',
  'dev',
  '["WordPress","Claude Code","Local","Thème","Design"]'::jsonb,
  'Next Gital',
  9,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Public","text":"Développeur junior Next Gital. Prérequis : Mac ou PC, Claude Code, Local (by Flywheel), VS Code."},{"type":"heading","text":"1. Travailler avec Claude Code"},{"type":"paragraph","text":"Claude Code n'est pas un chatbot : il lit et modifie directement les fichiers du projet, exécute des commandes et teste le site. Le rôle du développeur est de diriger, vérifier et valider."},{"type":"list","items":["Un objectif clair par demande — une tâche = une demande précise","Donner le contexte : quel site, quel dossier, quel résultat attendu","Laisser Claude explorer les fichiers existants avant de coder","Vérifier toujours le résultat dans le navigateur, pas seulement le code","Travailler par petites étapes : construire → tester → valider","Ne jamais valider à l'aveugle une mise en ligne ou une suppression"]},{"type":"heading2","text":"Structure d'un bon prompt"},{"type":"numbered","items":["Le contexte — « Sur le site WordPress local <nom-du-site>… »","L'objectif — « je veux ajouter / corriger / modifier… »","Le détail — valeurs exactes, textes, couleurs, comportement attendu","La vérification — « vérifie que la page s'affiche sans erreur »"]},{"type":"table","table":{"headers":["Prompt faible","Prompt fort"],"rows":[["refais la page d'accueil","Sur le site local tuning-car, modifie le titre du hero de front-page.php en « Location de voitures à Oujda », garde le design, puis vérifie que la page répond en HTTP 200"]]}},{"type":"heading","text":"2. Conception avant développement"},{"type":"callout","variant":"danger","title":"Règle d'or","text":"On conçoit avant de coder. Jamais de développement sans brief design validé."},{"type":"numbered","items":["Cadrer : type de site, cible, style, couleurs, polices, pages, fonctions","Générer 2-3 concepts visuels et comparer","Créer les maquettes HTML statiques (accueil, page intérieure, fiche produit)","Faire valider la maquette par le responsable ou le client","Seulement ensuite : transformer la maquette validée en thème WordPress"]},{"type":"heading","text":"3. Créer le site local (Local by Flywheel)"},{"type":"numbered","items":["Ouvrir Local → « + » (Create a new site)","Nommer le site (ex : nom-client)","Choisir « Preferred » (PHP + serveur + MySQL automatiques)","Définir l'identifiant et le mot de passe administrateur WordPress (les noter)","Add Site → le site se crée et démarre"]},{"type":"table","table":{"headers":["Action","Bouton dans Local"],"rows":[["Voir le site","Open site (ex : https://nom-client.local)"],["Administration","WP Admin"],["Fichiers","Go to site folder → app/public"],["Code","VS Code"],["Terminal WP-CLI","Site shell"]]}},{"type":"callout","variant":"info","title":"Dossier à indiquer à Claude Code","text":".../Local Sites/<nom-client>/app/public/wp-content/themes/"},{"type":"heading","text":"4. Construire un thème sur-mesure"},{"type":"numbered","items":["Créer le dossier du thème dans wp-content/themes/nom-theme/","style.css — en-tête du thème + design system (couleurs, polices)","functions.php — réglages, menus, scripts, Custom Post Types, champs personnalisés, Customizer","header.php / footer.php","front-page.php — page d'accueil","page.php, single.php, archive-*.php, single-*.php","template-*.php — contact, réservation, pages SEO","inc/ — modules séparés (ex : inc/seo.php pour Schema.org)"]},{"type":"heading","text":"5. Créer le contenu"},{"type":"numbered","items":["Activer le thème (Apparence → Thèmes)","Créer les pages et définir la page d'accueil (Réglages → Lecture)","Créer le menu (Apparence → Menus)","Ajouter le contenu (produits, articles, photos)","Renseigner les coordonnées via le Customizer"]},{"type":"heading","text":"6. Travailler directement dans les fichiers"},{"type":"callout","variant":"danger","title":"Règle Next Gital","text":"Claude Code modifie directement les fichiers du thème — il ne génère pas du code « à part » à recopier à la main."},{"type":"list","items":["❌ Coller du code donné en bloc sans savoir où il va","❌ Modifier un site en ligne directement sans sauvegarde","❌ Modifier le cœur de WordPress (wp-includes, wp-admin)"]},{"type":"heading","text":"7. Mettre en ligne le thème"},{"type":"numbered","items":["Compresser le dossier du thème en .zip","Sur le site en ligne : Apparence → Thèmes → Ajouter → Téléverser un thème","Choisir le .zip → Remplacer l'actuel par celui téléversé","Réglages → Permaliens → Enregistrer (régénère les liens)"]},{"type":"callout","variant":"warning","title":"Contenu vs code","text":"Le contenu (textes, produits, photos) se gère sur le site en ligne. Le thème (code) se prépare en local puis se téléverse."},{"type":"heading","text":"Checklist de livraison"},{"type":"checklist","items":["Toutes les pages s'affichent sans erreur (mobile + ordinateur)","Logo, couleurs et coordonnées corrects","Menu et liens fonctionnels","Formulaires testés (email bien reçu)","SEO de base : titres, meta descriptions, Schema, sitemap","Permaliens enregistrés","Site indexable (Réglages → Lecture : « décourager les moteurs » décoché)","Sauvegarde réalisée","Guide d'utilisation remis au client"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-wordpress-local-claude');

-- ── ng-dev-wordpress-reset-password (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-wordpress-reset-password',
  'Réinitialiser un mot de passe WordPress (Local / WP-CLI)',
  'Reprendre l''accès à un site WordPress local quand le mot de passe administrateur est oublié — méthode WP-CLI recommandée, AdminNeo en secours, et les erreurs à ne pas commettre.',
  'dev',
  '["WordPress","WP-CLI","Local","Mot de passe","Dépannage"]'::jsonb,
  'Next Gital',
  4,
  false,
  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Récupérer l'accès à un site WordPress local lorsque le mot de passe administrateur est oublié."},{"type":"callout","variant":"info","title":"Environnement","text":"Local (by Flywheel) · WordPress · WP-CLI · AdminNeo en secours."},{"type":"heading","text":"Méthode recommandée — WP-CLI"},{"type":"heading2","text":"1. Ouvrir le site dans Local"},{"type":"numbered","items":["Ouvrir Local","Sélectionner le site concerné","Vérifier que le site est démarré","Cliquer sur Site shell"]},{"type":"heading2","text":"2. Vérifier WP-CLI"},{"type":"code","text":"wp --info"},{"type":"paragraph","text":"Vérifier que WP-CLI répond (version, PHP, MySQL)."},{"type":"heading2","text":"3. Identifier l'utilisateur"},{"type":"code","text":"wp user list"},{"type":"paragraph","text":"Noter : ID, user_login, email."},{"type":"heading2","text":"4. Réinitialiser le mot de passe"},{"type":"code","text":"wp user update <user_login> --user_pass='<NOUVEAU_MOT_DE_PASSE>'"},{"type":"callout","variant":"success","title":"Résultat attendu","text":"Success: Updated user 1."},{"type":"callout","variant":"warning","title":"Message « sh: : command not found »","text":"Ce message peut apparaître dans l'environnement Local. Si « Success: Updated user X. » s'affiche, la modification a bien été effectuée."},{"type":"heading2","text":"5. Tester la connexion"},{"type":"paragraph","text":"Ouvrir <site>.local/wp-admin/ et se connecter avec le user_login (ou l'email) et le nouveau mot de passe."},{"type":"divider"},{"type":"heading","text":"Méthode de secours — AdminNeo"},{"type":"paragraph","text":"À utiliser uniquement si WP-CLI n'est pas disponible."},{"type":"numbered","items":["Dans Local : Database → Open AdminNeo","Sélectionner la base « local » → table wp_users","Afficher les données, repérer le compte administrateur"]},{"type":"callout","variant":"danger","title":"Ne jamais mettre le mot de passe en clair","text":"WordPress stocke un hash, pas le mot de passe. Modifier user_pass directement avec un mot de passe en clair casse la connexion. Toujours préférer WP-CLI, qui gère le hachage."},{"type":"heading","text":"Erreurs à éviter"},{"type":"list","items":["❌ « Modifier la table » — modifie la structure de la base, inutile ici","❌ Modifier directement user_pass avec un mot de passe en clair","❌ Modifier l'ID du compte","❌ Modifier user_login pour une simple récupération","❌ Supprimer l'utilisateur administrateur"]},{"type":"heading","text":"Version courte"},{"type":"code","text":"Local → Sélectionner le site → Site Shell\nwp user list\nwp user update <USERNAME> --user_pass='<NOUVEAU_MDP>'\n→ Success: Updated user X.\nOuvrir /wp-admin/ → tester la connexion"}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-wordpress-reset-password');

-- ── ng-dev-smtp-titan-hostinger (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-smtp-titan-hostinger',
  'Configurer l''envoi d''emails SMTP (Titan / Hostinger)',
  'Créer l''adresse professionnelle, poser les DNS (SPF, DKIM, MX), configurer le .env, concevoir le template email et valider la délivrabilité. Aucun service tiers, SMTP uniquement.',
  'dev',
  '["SMTP","Titan","Hostinger","Email","DNS","Formulaire"]'::jsonb,
  'Next Gital',
  6,
  true,
  $sop$[{"type":"callout","variant":"tip","title":"Principe","text":"Envoi et notifications par email basés uniquement sur SMTP. Aucun service tiers (Supabase, EmailJS, Firebase, SendGrid, Brevo, Mailgun)."},{"type":"callout","variant":"danger","title":"Sécurité","text":"Ne jamais partager le mot de passe SMTP dans une conversation, un ticket ou GitHub. Il vit uniquement dans un fichier .env non versionné."},{"type":"heading","text":"Étape 1 — Vérifier ou créer l'adresse email professionnelle"},{"type":"numbered","items":["Ouvrir Hostinger hPanel → Emails → Titan","Vérifier si l'adresse (ex : info@<domaine>) existe déjà","Si elle n'existe pas, la créer depuis hPanel"]},{"type":"heading","text":"Étape 2 — Vérifier les DNS Titan"},{"type":"table","table":{"headers":["Type","Nom","Priorité","Contenu","TTL"],"rows":[["TXT","titan1._domainkey","0","v=DKIM1; k=rsa; … (valeur fournie par Titan)","14400"],["TXT","@","0","v=spf1 include:spf.titan.email ~all","3600"],["MX","@","10","mx1.titan.email","3600"],["MX","@","20","mx2.titan.email","3600"]]}},{"type":"callout","variant":"info","title":"Pourquoi ces enregistrements","text":"Ils sont obligatoires pour la délivrabilité, éviter le spam, activer SPF / DKIM et sécuriser le SMTP. Vérifier que le DKIM Status affiche VERIFIED côté Titan."},{"type":"callout","variant":"warning","title":"Hostinger classique","text":"Si le domaine utilise la messagerie Hostinger et non Titan : SPF = v=spf1 include:_spf.mail.hostinger.com ~all et SMTP_HOST = smtp.hostinger.com."},{"type":"heading","text":"Étape 3 — Configurer le .env"},{"type":"code","text":"# Production — NE PAS COMMITTER\n\nSMTP_HOST=smtp.titan.email      # ou smtp.hostinger.com\nSMTP_PORT=465                   # 465 en SSL, 587 en TLS\nSMTP_USER=info@<domaine>\nSMTP_PASSWORD=\n\nMAIL_TO=info@<domaine>\nMAIL_FROM_NAME=Site <Nom Entreprise>\nSITE_URL=https://<domaine>\nMAIL_SUBJECT=Nouvelle demande reçue depuis le site web"},{"type":"code","text":"chmod 600 .env.local"},{"type":"heading","text":"Étape 4 — Design de l'email"},{"type":"list","items":["Reprendre les couleurs du site et le logo","Mise en page moderne, structure claire, responsive mobile","Afficher : nom, téléphone, email, message, date, source du formulaire","Reply-To = email de l'expéditeur pour répondre directement","Version texte brut en fallback","Compatible Gmail, Outlook, Apple Mail"]},{"type":"heading","text":"Étape 5 — Sécurité du formulaire"},{"type":"checklist","items":["Validation côté client ET côté serveur","Protection contre les injections et sanitization des entrées","Champ honeypot anti-bot","Rate limiting (ex : 3 requêtes / minute / IP)","Limite de taille du message (5 000 caractères)","Aucune fuite d'informations SMTP dans les réponses d'erreur","Aucun secret dans le code source, Git ou les logs"]},{"type":"heading","text":"Étape 6 — Vérifications avant livraison"},{"type":"checklist","items":["Envoi réel d'un email de test","Réception vérifiée sur Gmail et sur mobile","Rendu responsive vérifié","Aucune erreur SMTP dans les logs","Messages de succès et d'échec testés","Score mail-tester.com ≥ 8/10","Mot de passe SMTP rotationné s'il a été partagé en clair"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-smtp-titan-hostinger');

