INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-formulaire-rdv-deploiement',
  'Formulaire de rendez-vous — développement et mise en production',
  'Composant React + route API + variables d''environnement + template email, puis déploiement VPS (Docker / PM2 / systemd), test curl, test bout-en-bout et anti-spam DNS.',
  'dev',
  '["Formulaire","Next.js","SMTP","Déploiement","VPS"]'::jsonb,
  'Next Gital',
  7,
  false,
  $sop$[{"type":"callout","variant":"info","title":"Périmètre","text":"Site Next.js 14 (App Router) + TypeScript + Tailwind, envoi d'emails via SMTP (nodemailer)."},{"type":"heading","text":"1. Composant frontend"},{"type":"paragraph","text":"Fichier : src/components/ContactForm.tsx"},{"type":"list","items":["Champs : nom complet, email, téléphone, sujet, message","Validation côté client avec react-hook-form + zod","Messages d'erreur en français sous chaque champ","États gérés : idle / loading / success / error","Bouton désactivé pendant l'envoi avec spinner","Réinitialisation automatique après succès","Design responsive mobile-first, support RTL si FR/AR","Accessibilité : labels, aria-attributes, focus visible"]},{"type":"heading","text":"2. Route API"},{"type":"paragraph","text":"Fichier : src/app/api/contact/route.ts"},{"type":"list","items":["Endpoint POST qui reçoit les données","Validation serveur avec zod — ne jamais faire confiance au client","Rate limiting : 3 requêtes par minute par IP","Champ honeypot caché pour bloquer les bots","Envoi de l'email via nodemailer","Codes HTTP corrects : 200, 400, 429, 500","Logs serveur en cas d'erreur, sans exposer d'infos sensibles"]},{"type":"heading","text":"3. Variables d'environnement (.env.local, dans .gitignore)"},{"type":"code","text":"SMTP_HOST=\nSMTP_PORT=587\nSMTP_SECURE=false\nSMTP_USER=\nSMTP_PASSWORD=\nSMTP_FROM=\"Nom du site <noreply@example.com>\"\nSMTP_TO=contact@example.com"},{"type":"heading","text":"4. Déploiement sur le VPS"},{"type":"numbered","items":["git pull origin main sur le serveur","Créer le .env.local à la racine (jamais dans le dépôt)","chmod 600 .env.local","Rebuild et relance selon la plateforme"]},{"type":"code","text":"# Docker\ndocker compose down\ndocker compose up -d --build\n# (docker-compose.yml doit contenir env_file: .env.local)\n\n# PM2\nnpm ci && npm run build && pm2 restart all --update-env\n\n# systemd\nnpm ci && npm run build && sudo systemctl restart <service>"},{"type":"heading","text":"5. Vérifier le déploiement"},{"type":"code","text":"curl -i -X POST https://<domaine>/api/appointment \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"name\":\"Test\",\"email\":\"votre@email.com\",\"phone\":\"+212600000000\",\"reason\":\"Consultation\",\"appointment_date\":\"2026-06-01\",\"appointment_time\":\"10:00\",\"locale\":\"fr\"}'"},{"type":"table","table":{"headers":["Code","Diagnostic","Action"],"rows":[["200 {\"success\":true}","Tout fonctionne","Vérifier la boîte de réception"],["503 smtp_not_configured","Variables non lues","Rebuild, vérifier le chargement de .env.local"],["502 send_failed","SMTP refuse la connexion","Mot de passe incorrect ou IP du VPS bloquée"],["Timeout / 502 nginx","L'app ne tourne pas","Vérifier docker ps ou pm2 status"]]}},{"type":"heading","text":"6. Test bout-en-bout"},{"type":"numbered","items":["Ouvrir la page du formulaire en navigation privée","Remplir toutes les étapes avec sa propre adresse email","Soumettre → le bandeau de confirmation doit s'afficher","Vérifier les 2 boîtes : destinataire interne + email de confirmation client"]},{"type":"heading","text":"7. Anti-spam DNS — à faire une fois"},{"type":"table","table":{"headers":["Type","Nom","Valeur"],"rows":[["TXT","@","v=spf1 include:_spf.mail.hostinger.com ~all"],["TXT","_dmarc","v=DMARC1; p=none; rua=mailto:contact@<domaine>"],["DKIM","(auto)","Activer DKIM dans Emails → adresse → Manage"]]}},{"type":"paragraph","text":"Propagation : 15 min à 1 h. Tester ensuite sur mail-tester.com (score visé ≥ 8/10)."},{"type":"heading","text":"Dépannage"},{"type":"table","table":{"headers":["Symptôme","Cause probable","Solution"],"rows":[["Échec sur VPS uniquement",".env.local absent ou non chargé","Recréer le fichier + rebuild"],["Erreur EAUTH","Mauvais mot de passe","Régénérer depuis le panneau email"],["ETIMEDOUT / ECONNREFUSED","Firewall VPS bloque le port sortant 465","Autoriser le port 465 en sortie"],["Emails reçus mais en spam","DNS manquants","Poser SPF + DKIM + DMARC"]]}}]$sop$::jsonb
