-- ── ng-dev-supabase-react-vite (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-supabase-react-vite',
  'Connecter une application React/Vite à Supabase',
  'De zéro à opérationnel : variables d''environnement, schéma SQL, RLS, triggers, configuration du dashboard, création du compte admin, seed et vérification complète.',
  'dev',
  '["Supabase","React","Vite","PostgreSQL","RLS","Auth"]'::jsonb,
  'Next Gital',
  10,
  true,
  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Connecter n'importe quelle application React + Vite + TypeScript à un projet Supabase : variables, schéma, sécurité RLS, utilisateurs par rôle, validation."},{"type":"heading","text":"Partie 1 — Variables d'environnement"},{"type":"numbered","items":["Dashboard Supabase → Settings → API","Copier : Project URL, clé anon/public, clé service_role, Project ID","Créer le fichier .env à la racine (même niveau que package.json)"]},{"type":"code","text":"VITE_SUPABASE_URL=https://[PROJECT_ID].supabase.co\nVITE_SUPABASE_PUBLISHABLE_KEY=[ANON_KEY]\nVITE_SUPABASE_SERVICE_ROLE_KEY=[SERVICE_ROLE_KEY]\nVITE_SUPABASE_PROJECT_ID=[PROJECT_ID]"},{"type":"list","items":["Aucun espace autour du =","Aucun guillemet autour des valeurs",".env ajouté dans .gitignore — ne jamais committer les clés"]},{"type":"paragraph","text":"Le client doit lire exclusivement les variables VITE_, jamais de clé en dur :"},{"type":"code","text":"import { createClient } from '@supabase/supabase-js'\n\nconst SUPABASE_URL      = import.meta.env.VITE_SUPABASE_URL as string\nconst SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string\n\nexport const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {\n  auth: { storage: localStorage, persistSession: true, autoRefreshToken: true },\n})"},{"type":"heading","text":"Partie 2 — Schéma de base de données"},{"type":"paragraph","text":"SQL Editor → créer les ENUM métier, puis la table profiles (obligatoire pour les rôles) :"},{"type":"code","text":"CREATE TABLE public.profiles (\n  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id    UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name  TEXT,\n  email      TEXT,\n  role       TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"View own profile\"   ON public.profiles FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Insert own profile\" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = user_id);\nCREATE POLICY \"Update own profile\" ON public.profiles FOR UPDATE USING (auth.uid() = user_id);"},{"type":"callout","variant":"danger","title":"RLS obligatoire","text":"Chaque table métier doit avoir ENABLE ROW LEVEL SECURITY + des politiques SELECT / INSERT / UPDATE. Une table sans RLS est publiquement lisible."},{"type":"heading","text":"Partie 3 — Triggers automatiques"},{"type":"code","text":"-- Créer le profil automatiquement à l'inscription\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$\nBEGIN\n  INSERT INTO public.profiles (user_id, full_name)\n  VALUES (NEW.id, NEW.raw_user_meta_data ->> 'full_name');\n  RETURN NEW;\nEND;\n$fn$;\n\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();"},{"type":"heading","text":"Partie 4 — Configuration du dashboard"},{"type":"numbered","items":["Auth → Providers → Email : désactiver « Confirm email » en développement","Auth → URL Configuration : Site URL = http://localhost:8080 (dev) ou https://<domaine> (prod)","Redirect URLs : http://localhost:8080/** (dev) ou https://<domaine>/** (prod)"]},{"type":"heading","text":"Partie 5 — Démarrage et compte admin"},{"type":"code","text":"npm install\nnpm list @supabase/supabase-js\nnpm run dev"},{"type":"paragraph","text":"Créer le compte admin depuis l'application, puis le promouvoir :"},{"type":"code","text":"UPDATE public.profiles SET role = 'admin'\nWHERE user_id = (SELECT id FROM auth.users WHERE email = 'admin@<projet>');"},{"type":"paragraph","text":"Se déconnecter puis se reconnecter — la navigation admin complète doit apparaître."},{"type":"heading","text":"Erreurs fréquentes"},{"type":"table","table":{"headers":["Erreur","Cause","Solution"],"rows":[["Invalid API key","Mauvaise clé dans .env","Recopier depuis Settings → API"],["Failed to fetch","URL incorrecte ou projet suspendu","Vérifier VITE_SUPABASE_URL"],["relation \"…\" does not exist","Table non créée","Exécuter la migration correspondante"],["permission denied for table","RLS sans politique","Ajouter les policies manquantes"],["new row violates row-level security","INSERT sans user_id valide","S'assurer que user_id = auth.uid()"],["net.http_post does not exist","Extension pg_net non activée","Database → Extensions → pg_net"],["Connexion impossible après inscription","Confirmation email active","Désactiver Confirm email en dev"]]}},{"type":"heading","text":"Checklist finale"},{"type":"checklist","items":[".env présent avec les 4 variables VITE_ et ajouté au .gitignore","Aucune clé en dur dans le code","Toutes les tables créées avec RLS activé et policies","Trigger on_auth_user_created actif","Site URL configurée dans Auth","npm run dev démarre sans erreur","Compte admin créé et promu","Console navigateur propre (0 erreur Supabase)","INSERT de test visible dans le Table Editor"]}]$sop$::jsonb
