INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-pgnet-google-sheets',
  'Activer pg_net et synchroniser Supabase avec Google Sheets',
  'Activer l''extension pg_net, réactiver les triggers de notification, tester l''envoi vers Google Sheets et diagnostiquer via net._http_response.',
  'dev',
  '["Supabase","pg_net","Google Sheets","Trigger","Automatisation"]'::jsonb,
  'Next Gital',
  4,
  false,
  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Chaque insertion en base déclenche automatiquement l'envoi des données vers Google Sheets via le trigger de notification."},{"type":"callout","variant":"info","title":"Prérequis","text":"Accès Owner ou Admin du projet Supabase · Fichier Google Sheets ouvert et accessible."},{"type":"heading","text":"Étapes"},{"type":"heading2","text":"1. Activer l'extension"},{"type":"numbered","items":["Dashboard Supabase → Database → Extensions","Rechercher pg_net","Cliquer sur pg_net → Enable extension"]},{"type":"callout","variant":"success","title":"Résultat attendu","text":"Bouton vert, mention « Enabled »."},{"type":"heading2","text":"2. Vérifier dans le SQL Editor"},{"type":"code","text":"SELECT * FROM pg_extension WHERE extname = 'pg_net';"},{"type":"paragraph","text":"Résultat attendu : 1 ligne retournée."},{"type":"heading2","text":"3. Réactiver les triggers sur les tables concernées"},{"type":"code","text":"ALTER TABLE <table_1> ENABLE TRIGGER ALL;\nALTER TABLE <table_2> ENABLE TRIGGER ALL;\n-- … répéter pour chaque table synchronisée"},{"type":"paragraph","text":"Résultat attendu : Success. No rows returned."},{"type":"heading2","text":"4. Tester l'envoi"},{"type":"paragraph","text":"Insérer une ligne de test dans une table synchronisée, avec une valeur reconnaissable (ex : « Test Google Sheets »)."},{"type":"paragraph","text":"Résultat attendu : Success. 1 row affected."},{"type":"heading2","text":"5. Vérifier dans Google Sheets"},{"type":"paragraph","text":"Ouvrir le fichier, attendre 30 secondes, vérifier la nouvelle ligne."},{"type":"heading2","text":"6. En cas d'échec — diagnostiquer"},{"type":"code","text":"SELECT id, status_code, error_msg\nFROM net._http_response\nORDER BY created DESC\nLIMIT 5;"},{"type":"paragraph","text":"Transmettre le résultat au responsable technique."},{"type":"heading","text":"Checklist finale"},{"type":"checklist","items":["pg_net visible comme « Enabled » dans le dashboard","SELECT pg_extension retourne 1 ligne","ENABLE TRIGGER ALL → Success sur toutes les tables","INSERT test → Success (1 row affected)","Nouvelle ligne visible dans Google Sheets sous 30 secondes"]}]$sop$::jsonb
