INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-localhost-ports',
  'Registre des ports localhost — un projet, une URL',
  'Règle anti-confusion multi-projets : chaque projet a une URL localhost unique et permanente, jamais réutilisée, jamais empruntée à un autre projet.',
  'dev',
  '["Localhost","Ports","Organisation","Multi-projets"]'::jsonb,
  'Next Gital',
  3,
  false,
  $sop$[{"type":"callout","variant":"danger","title":"Règle fondamentale","text":"Chaque projet a UNE seule URL localhost. Ne jamais mélanger les URL entre projets. Ne jamais réutiliser un port déjà attribué. Ne jamais deviner au hasard."},{"type":"heading","text":"Registre — source de vérité"},{"type":"table","table":{"headers":["Projet","URL"],"rows":[["Projet A","http://localhost:3000"],["Projet B","http://localhost:3001"],["Projet C","http://localhost:3002"]]}},{"type":"paragraph","text":"Maintenir ce tableau à jour dans le SOP à chaque nouveau projet."},{"type":"heading","text":"Règles"},{"type":"numbered","items":["Si le projet existe dans le registre → utiliser son URL exacte, ne jamais changer le port","Si le projet n'existe pas → créer une nouvelle URL unique avec le port suivant disponible (3003, 3004…) et l'ajouter au registre","Ne jamais réutiliser un port existant","Ne jamais attribuer la même URL à deux projets","Ne jamais reprendre l'URL d'un autre projet"]},{"type":"heading","text":"Vérification avant de donner une URL"},{"type":"numbered","items":["Le projet existe-t-il déjà dans le registre ? → utiliser son URL","Sinon → générer un nouveau port unique","S'assurer qu'il n'y a aucune duplication"]},{"type":"code","text":"lsof -i :3000        # qui occupe le port ?\nkill -9 <PID>        # libérer si nécessaire"},{"type":"heading","text":"Format de réponse"},{"type":"code","text":"Projet : [Nom]\nURL    : http://localhost:XXXX"},{"type":"callout","variant":"warning","title":"En cas de conflit","text":"Si un doublon ou une mauvaise URL est détecté : s'arrêter et signaler « Erreur : conflit de port ou mélange de projets détecté »."}]$sop$::jsonb
