INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-whatsapp-twilio',
  'Notifications WhatsApp automatiques (Twilio)',
  'Envoyer une notification WhatsApp au client à chaque étape du cycle de vie : choix du fournisseur, sandbox, variables, architecture, base de données, règles métier, déploiement et incidents.',
  'dev',
  '["WhatsApp","Twilio","Notifications","API","Automatisation"]'::jsonb,
  'Next Gital',
  9,
  false,
  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Envoyer automatiquement une notification WhatsApp au client à la création, au départ en livraison et à la livraison effectuée, avec un lien de suivi."},{"type":"heading","text":"1. Choix du fournisseur"},{"type":"paragraph","text":"Twilio WhatsApp API retenu : intégration facile, sandbox gratuit, facturation à l'usage, documentation complète."},{"type":"table","table":{"headers":["Fournisseur","Coût estimé / 4 500 messages"],"rows":[["Twilio","~850 MAD"],["MessageBird","~790 MAD"],["Infobip","~870 MAD"],["360dialog","~1 150 MAD"]]}},{"type":"heading","text":"2. Configuration du compte Twilio"},{"type":"numbered","items":["Créer un compte sur twilio.com (offre Trial)","Messaging → Try it Out → Send a WhatsApp Message pour activer le Sandbox","Depuis le téléphone : envoyer le code « join <mot-cle> » au numéro sandbox","Vérifier la réception du message « You are all set! »","Récupérer l'Account SID et l'Auth Token depuis le tableau de bord"]},{"type":"callout","variant":"warning","title":"Limites du sandbox","text":"Valable 72 heures · seuls les numéros inscrits reçoivent les messages · non adapté à la production finale."},{"type":"heading","text":"3. Variables d'environnement"},{"type":"code","text":"# Développement (.env)\nTWILIO_ACCOUNT_SID=\nTWILIO_AUTH_TOKEN=\nTWILIO_WHATSAPP_FROM=whatsapp:+<numero_sandbox>\nTEST_WHATSAPP_TO=whatsapp:+<numero_test>\nPUBLIC_BASE_URL=http://localhost:8081\n\n# Production (Dokploy → Environment)\nPUBLIC_BASE_URL=https://<domaine>"},{"type":"callout","variant":"danger","title":"Jamais dans Git","text":"Ne jamais versionner le fichier .env ni les tokens Twilio."},{"type":"heading","text":"4. Architecture technique"},{"type":"table","table":{"headers":["Fichier","Responsabilité"],"rows":[["server/services/whatsapp.js","Communication avec Twilio, gestion des erreurs, protection contre les crashs"],["server/services/<entite>Messenger.js","Génération des messages, résolution du destinataire, journalisation"],["server/routes/whatsapp.js","Endpoint de test POST /api/whatsapp/test"],["database/…​.sql","Migration : colonne téléphone + table de journal"]]}},{"type":"heading","text":"5. Base de données"},{"type":"code","text":"ALTER TABLE <entite> ADD COLUMN customer_phone TEXT;\n\nCREATE TABLE <entite>_messages (\n    id          BIGSERIAL PRIMARY KEY,\n    <entite>_id UUID REFERENCES <entite>(id),\n    event       TEXT,\n    to_number   TEXT,\n    twilio_sid  TEXT,\n    status      TEXT,\n    error       TEXT,\n    sent_at     TIMESTAMPTZ\n);"},{"type":"heading","text":"6. Règles métier"},{"type":"list","items":["Priorité du destinataire : champ téléphone de l'entité → téléphone du partenaire lié → sinon journaliser un « skip »","Fire & forget : l'échec d'un message WhatsApp ne doit JAMAIS bloquer la création, la mise à jour ou la livraison","Toutes les tentatives sont enregistrées dans la table de journal","Formats de numéro acceptés : +212XXXXXXXXX, 212XXXXXXXXX, 06XXXXXXXX, whatsapp:+212XXXXXXXXX — validation +\\d{8,15}"]},{"type":"code","text":"notify(...).catch(console.error)"},{"type":"heading","text":"7. Déploiement en production"},{"type":"numbered","items":["git push","Exécuter la migration SQL","Ajouter les variables Twilio dans Environment","Redeploy","Vérifier les logs","Tester avec un numéro inscrit au sandbox"]},{"type":"heading","text":"8. Incidents possibles"},{"type":"table","table":{"headers":["Erreur","Cause","Solution"],"rows":[["[whatsapp] disabled","Variables absentes","Vérifier Environment"],["Authenticate (20003)","Auth Token incorrect","Recopier depuis Twilio"],["Channel not found","Sandbox expiré","Refaire le join"],["Aucun message reçu","Numéro non inscrit","Envoyer le code join"],["Lien localhost dans le message","PUBLIC_BASE_URL incorrect","Mettre l'URL de production"]]}},{"type":"heading","text":"9. Passage en production officielle"},{"type":"numbered","items":["Créer un WhatsApp Sender officiel","Acheter un numéro WhatsApp Business","Effectuer la vérification Meta Business","Créer les modèles de message et attendre la validation Meta","Adapter le service messenger et mettre à jour TWILIO_WHATSAPP_FROM"]},{"type":"heading","text":"Validation"},{"type":"checklist","items":["Logs locaux : [whatsapp] enabled","POST /api/whatsapp/test → message reçu en moins de 5 secondes","Message de création reçu","Message « en cours de livraison » reçu","Message « livrée » reçu","status = sent pour chaque événement dans la table de journal"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-whatsapp-twilio');

-- ── ng-dev-audit-securite-app (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-audit-securite-app',
  'Audit de sécurité applicatif — méthode et rapport',
  'Modèle de menace, 12 domaines à auditer (secrets, auth, RBAC, API, OWASP, frontend, base, infra, cloud, CI/CD, dépendances, monitoring), notation CVSS et scorecard final.',
  'dev',
  '["Sécurité","Audit","OWASP","Pentest","Infrastructure"]'::jsonb,
  'Next Gital',
  10,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Principe","text":"Ne jamais supposer qu'un système est sécurisé sans preuve. Si la preuve manque, marquer le contrôle NON VÉRIFIÉ et expliquer comment le vérifier."},{"type":"callout","variant":"info","title":"Objectif business","text":"Protéger les données clients, les opérations, le chiffre d'affaires, la réputation, l'infrastructure et la propriété intellectuelle."},{"type":"heading","text":"1. Modèle de menace — toujours en premier"},{"type":"heading2","text":"Surface d'attaque"},{"type":"list","items":["Endpoints publics","Interfaces admin","Systèmes d'authentification","APIs","Webhooks","Bases de données","Buckets de stockage","CI/CD","Dépôts Git","Intégrations tierces"]},{"type":"heading2","text":"Acteurs de la menace"},{"type":"list","items":["Internautes anonymes","Utilisateurs authentifiés","Employés malveillants","Concurrents","Bots automatisés","Credential stuffing","Opérateurs de ransomware"]},{"type":"heading2","text":"Classification des données"},{"type":"list","items":["Publique","Interne","Confidentielle","Sensible","Données personnelles (PII)","Données financières","Données médicales"]},{"type":"heading2","text":"Frontières de confiance"},{"type":"list","items":["Navigateur → Backend","Backend → Base de données","Backend → APIs tierces","Interne → Services publics"]},{"type":"heading","text":"2. Les 12 domaines à auditer"},{"type":"table","table":{"headers":["#","Domaine","Points de contrôle"],"rows":[["1","Secrets & credentials","Exposition .env, fuites Git, secrets en dur, clés API, secrets CI"],["2","Authentification","Expiration et validation JWT, refresh tokens, sessions, politique de mot de passe, MFA, récupération de compte"],["3","Autorisation","RBAC, accès admin, protection des routes, escalade de privilèges, isolation multi-tenant, RLS"],["4","Sécurité API","Rate limiting, validation des entrées, filtrage des sorties, IDOR, mass assignment, exposition de clés"],["5","OWASP Top 10","Broken access control, échecs cryptographiques, injection, design non sécurisé, mauvaise configuration, composants vulnérables, SSRF"],["6","Frontend","XSS, DOM XSS, localStorage, source maps, CSP, clickjacking, fuites de données"],["7","Base de données","Permissions PostgreSQL, RLS, exposition de données, injection SQL, chiffrement des backups, rétention"],["8","Infrastructure","Ports ouverts, firewall, durcissement SSH, fail2ban, exposition Docker, reverse proxy, TLS, headers de sécurité"],["9","Cloud / BaaS","Permissions des buckets, buckets publics, mauvais usage du service role, Edge Functions, exposition de la base"],["10","CI/CD","GitHub Actions, secrets de déploiement, artefacts de build, fuites de variables"],["11","Dépendances","npm audit, CVE connues, paquets obsolètes, risques supply chain"],["12","Monitoring & IR","Logs d'audit, alerting, stratégie de backup, plan de récupération, préparation à l'incident"]]}},{"type":"heading","text":"3. Notation de la sévérité"},{"type":"table","table":{"headers":["Niveau","CVSS","Signification"],"rows":[["🔴 CRITICAL","9.0 – 10","Compromission immédiate possible"],["🟠 HIGH","7.0 – 8.9","Risque de sécurité sérieux"],["🟡 MEDIUM","4.0 – 6.9","Nécessite une remédiation"],["🟢 LOW","0.1 – 3.9","Problème mineur"],["ℹ️ INFO","—","Observation seulement"]]}},{"type":"heading","text":"4. Format de chaque constat"},{"type":"template","text":"SÉVÉRITÉ : 🔴 / 🟠 / 🟡 / 🟢\n\nVULNÉRABILITÉ :\n[Nom]\n\nCVSS :\n[Score estimé]\n\nLOCALISATION :\n[Fichier / Endpoint / Service]\n\nSCÉNARIO D'ATTAQUE :\n[Comment un attaquant exploiterait précisément la faille]\n\nIMPACT BUSINESS :\n- Risque financier\n- Risque de réputation\n- Impact client\n- Impact conformité\n\nCORRECTION :\n[Code, configuration, changement d'architecture ou commande exacte]\n\nVÉRIFICATION :\n[Commandes curl, procédure de test, checklist]"},{"type":"heading","text":"5. Livrables du rapport"},{"type":"numbered","items":["Résumé exécutif : total des constats, répartition Critical/High/Medium/Low, Top 5 des risques à corriger immédiatement","Le détail de chaque constat au format ci-dessus","La scorecard finale"]},{"type":"paragraph","text":"Scorecard : Authentification /10 · Autorisation /10 · API /10 · Frontend /10 · Base de données /10 · Infrastructure /10 · CI/CD /10 · Monitoring /10 → Score global /100."},{"type":"heading","text":"Règles"},{"type":"list","items":["Jamais de conseil générique","Toujours expliquer l'impact pour l'attaquant","Prioriser par le risque business","Ne jamais supposer qu'un contrôle existe","Marquer les contrôles incertains NON VÉRIFIÉ","Fournir les commandes et correctifs exacts","Aucune exploitation destructive, aucun brute-force pendant l'audit"]}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-audit-securite-app');

-- ── ng-dev-audit-securite-wordpress (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-audit-securite-wordpress',
  'Audit de sécurité WordPress / WooCommerce',
  'Passer en revue le cœur, les extensions, le thème, WooCommerce, les fichiers sensibles, wp-config, les comptes admin, XML-RPC, la REST API, HTTPS, les headers et la base — puis prioriser les corrections.',
  'dev',
  '["WordPress","WooCommerce","Sécurité","Audit","Hardening"]'::jsonb,
  'Next Gital',
  9,
  false,
  $sop$[{"type":"callout","variant":"info","title":"Nature de l'audit","text":"Audit technique non destructif. Aucune exploitation, aucun brute-force, aucune modification de la base pendant l'audit."},{"type":"callout","variant":"warning","title":"Rappel","text":"Un site n'est jamais « 100 % sécurisé ». La sécurité consiste à réduire les risques et à limiter l'impact d'une compromission."},{"type":"heading","text":"Périmètre à auditer"},{"type":"table","table":{"headers":["Élément","Points de contrôle"],"rows":[["WordPress Core","Version installée vs disponible, intégrité des fichiers, mises à jour automatiques, fichiers inconnus"],["Extensions","Version, dernière mise à jour, vulnérabilités connues, extension abandonnée, extensions inactives à supprimer"],["Thème","Version obsolète, fichiers modifiés, fichiers PHP inconnus, code obfusqué, absence de child theme"],["WooCommerce","Version, extensions de paiement, REST API, webhooks, checkout, sessions, cookies sécurisés, HTTPS"],["Fichiers sensibles","wp-config.php, .htaccess, debug.log, readme.html, sauvegardes, .zip, .sql, .bak, .git, PHP dans uploads"],["wp-config.php","Permissions, clés et salts, WP_DEBUG, WP_DEBUG_DISPLAY, DISALLOW_FILE_EDIT"],["Comptes","Administrateurs inconnus, comptes inutilisés, privilèges excessifs, identifiants devinables, absence de 2FA"],["Authentification","HTTPS, protection de la page de connexion, limitation des tentatives, 2FA, cookies sécurisés, XML-RPC"],["REST API","/wp-json/ — exposition d'informations ou de données utilisateurs"],["HTTPS / SSL","Certificat valide, expiration, redirection HTTP→HTTPS, TLS, mixed content, HSTS"],["Headers","CSP, HSTS, X-Content-Type-Options, X-Frame-Options, Referrer-Policy, Permissions-Policy"],["Permissions fichiers","Droits d'écriture limités aux dossiers qui en ont réellement besoin"],["Uploads","Fichiers PHP inattendus, exécutables, fichiers récemment modifiés, scripts suspects"],["Base de données","Utilisateurs suspects, options inhabituelles, scripts injectés, cron jobs suspects, autoload volumineux"],["Serveur","Version PHP (viser 8.3+), MySQL/MariaDB, exposition d'informations serveur, logs, TLS"]]}},{"type":"callout","variant":"warning","title":"Faux positifs","text":"La présence de eval() ou base64_decode() n'est pas une preuve de malware : analyser le contexte. Un fichier PHP dans uploads déclenche une analyse approfondie mais n'est pas automatiquement classé malveillant."},{"type":"callout","variant":"danger","title":"Secrets","text":"Les identifiants, clés et salts ne doivent JAMAIS apparaître dans le rapport. Les masquer sous la forme ********."},{"type":"heading","text":"Mode debug en production"},{"type":"paragraph","text":"Un site de production ne doit pas afficher publiquement les erreurs PHP : cela révèle chemins internes, noms de fichiers, informations serveur et structure du site."},{"type":"code","text":"define('WP_DEBUG', false);\ndefine('WP_DEBUG_DISPLAY', false);\ndefine('WP_DEBUG_LOG', true);   // logs protégés uniquement\ndefine('DISALLOW_FILE_EDIT', true);"},{"type":"heading","text":"Score de sécurité"},{"type":"table","table":{"headers":["Score","Classification"],"rows":[["90–100","Excellent"],["80–89","Bon"],["70–79","Correct"],["50–69","À améliorer"],["0–49","Risque élevé"]]}},{"type":"heading","text":"Plan de correction priorisé"},{"type":"numbered","items":["Priorité 1 — Critique : vulnérabilités confirmées, fichiers sensibles exposés, comptes admin suspects, malware, secrets exposés","Priorité 2 — Haute : WordPress obsolète, extensions vulnérables, thème obsolète, configuration serveur faible, permissions dangereuses","Priorité 3 — Moyenne : security headers, configuration WordPress, XML-RPC, REST API, logs, hardening","Priorité 4 — Faible : nettoyage des extensions inutilisées, réduction de la surface d'attaque, maintenance"]},{"type":"callout","variant":"info","title":"Limitation de l'audit","text":"Un audit automatisé ne garantit jamais l'absence totale de vulnérabilités. Certaines nécessitent une revue manuelle du code, de la configuration serveur, des extensions et du thème."}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-audit-securite-wordpress');

-- ── ng-dev-audit-qa-production (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-audit-qa-production',
  'Audit QA complet avant mise en production',
  '7 phases obligatoires — structure, qualité du code, fonctionnalités, UI/UX, performance, sécurité, build — avec protocole de correction et rapport de production readiness.',
  'dev',
  '["QA","Audit","Production","Build","Checklist"]'::jsonb,
  'Next Gital',
  8,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Blocage de livraison","text":"Interdit de livrer si : le build échoue · le login échoue · des erreurs runtime, console ou API existent · une route est cassée · un bug critique subsiste. Corriger d'abord, livrer ensuite."},{"type":"heading","text":"Phase 1 — Structure et fichiers"},{"type":"checklist","items":["Tous les fichiers référencés dans les imports existent","Aucun fichier vide ou contenant un placeholder (« TODO », « add logic here », « coming soon »)","Tous les composants correctement exportés et importés",".env.example contient TOUTES les variables requises","README.md présent avec de vraies instructions de setup"]},{"type":"heading","text":"Phase 2 — Qualité du code"},{"type":"checklist","items":["Zéro erreur TypeScript (pas de `any` sans raison)","Zéro warning ni erreur ESLint","Imports, variables et code mort supprimés","Chaque fonction async a une gestion d'erreur try/catch","Chaque appel API gère loading, succès ET erreur","Aucun secret, clé API ou identifiant en dur","Tous les formulaires ont une validation","Destructurations avec valeurs par défaut pour éviter les crashs"]},{"type":"heading","text":"Phase 3 — Fonctionnalités"},{"type":"checklist","items":["Authentification : inscription → connexion → déconnexion → routes protégées","CRUD principal : créer → lire → modifier → supprimer","Navigation : chaque lien mène à la bonne page","Formulaires : soumission → état de chargement → retour succès/erreur","Recherche et filtres : les résultats se mettent à jour correctement","Modales et tiroirs : ouverture → interaction → fermeture","Connexion backend correctement configurée","Variables d'environnement consommées correctement","Politiques RLS correctes le cas échéant"]},{"type":"heading","text":"Phase 4 — UI / UX"},{"type":"checklist","items":["Chaque page a un état de chargement (skeleton, pas une page blanche)","Chaque état vide a un message ou un CTA","Chaque état d'erreur affiche un message lisible","Le mode sombre fonctionne sur TOUTES les pages","Responsive testé : mobile 375px / tablette 768px / desktop","Toasts déclenchés correctement","Les animations ne cassent pas la mise en page","Modales fermables (bouton X + clic extérieur)","Sidebar repliable sur mobile","Élément de navigation actif toujours mis en évidence"]},{"type":"heading","text":"Phase 5 — Performance"},{"type":"checklist","items":["Routes en React.lazy() + Suspense (code splitting)","Images avec width/height explicites (évite le layout shift)","staleTime et cacheTime configurés sur TanStack Query","React.memo là où c'est utile — pas de re-render inutile","Debounce sur les champs de recherche","Aucun problème de requêtes N+1"]},{"type":"heading","text":"Phase 6 — Sécurité"},{"type":"checklist","items":["Aucune donnée sensible non chiffrée dans localStorage","Toutes les routes API sensibles exigent une authentification","Sanitization des entrées avant les opérations en base","CORS correctement configuré","Rate limiting actif sur les endpoints d'authentification","Aucune injection SQL possible dans les requêtes brutes"]},{"type":"heading","text":"Phase 7 — Build et déploiement"},{"type":"code","text":"npm run build      # corriger TOUTES les erreurs jusqu'au succès\nnpm run lint       # corriger toutes les erreurs de lint\nnpx tsc --noEmit   # corriger toutes les erreurs TypeScript"},{"type":"checklist","items":["La sortie /dist fonctionne correctement","Dockerfile ou config de déploiement valide (si présent)","Toutes les variables documentées dans .env.example"]},{"type":"heading","text":"Protocole de correction"},{"type":"numbered","items":["Annoncer clairement : « PROBLÈME TROUVÉ : [description] »","Corriger immédiatement, sans demander","Confirmer : « CORRIGÉ : [ce qui a été fait] »","Passer au contrôle suivant"]},{"type":"heading","text":"Rapport final"},{"type":"template","text":"========================================\n✅ RAPPORT DE PRODUCTION READINESS\n========================================\nPHASE 1 — Structure       : [PASS / X corrections]\nPHASE 2 — Qualité du code : [PASS / X corrections]\nPHASE 3 — Fonctionnalités : [PASS / X corrections]\nPHASE 4 — UI/UX           : [PASS / X corrections]\nPHASE 5 — Performance     : [PASS / X corrections]\nPHASE 6 — Sécurité        : [PASS / X corrections]\nPHASE 7 — Build           : [PASS / X corrections]\n----------------------------------------\nTOTAL DE CORRECTIONS : X\nSTATUT BUILD : ✅ PRÊT POUR LE DÉPLOIEMENT\n========================================"}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-audit-qa-production');

-- ── ng-dev-audit-responsive (dev) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-audit-responsive',
  'Audit responsive obligatoire avant livraison',
  'Tester les 10 breakpoints sur chaque page et chaque composant, corriger immédiatement, retester, puis produire le rapport PASS/FAIL page par page.',
  'dev',
  '["Responsive","QA","Mobile","Tailwind","Livraison"]'::jsonb,
  'Next Gital',
  7,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Ne jamais supposer","text":"Le site n'est pas responsive tant qu'il n'a pas été vérifié. Il faut vérifier, détecter, corriger, retester et rapporter."},{"type":"heading","text":"1. Breakpoints obligatoires"},{"type":"list","items":["1920px — Desktop large","1440px — Desktop","1366px — Laptop","1280px — Laptop small","1024px — Tablette paysage","768px — Tablette portrait","430px — Mobile large","390px — iPhone","375px — Mobile standard","360px — Petit mobile"]},{"type":"heading","text":"2. Périmètre"},{"type":"paragraph","text":"Toutes les pages, toutes les sections et tous les composants réutilisables : header, navigation, menu mobile, hero, sections de contenu, cartes, grilles, images, formulaires, boutons, tableaux, modales, popups, footer, mode sombre."},{"type":"heading","text":"3. Contrôles par zone"},{"type":"table","table":{"headers":["Zone","À vérifier"],"rows":[["Header & navigation","Logo visible et bien dimensionné, menu mobile qui s'ouvre et se ferme, aucun débordement, aucun scroll horizontal"],["Hero","Texte lisible, titres qui s'adaptent, images responsives, boutons visibles et cliquables, aucun chevauchement"],["Sections de contenu","Aucun scroll horizontal, aucune mise en page cassée, typographie et espacements adaptatifs"],["Cartes & grilles","Alignement desktop, empilement correct sur tablette et mobile, espacement égal, aucun débordement"],["Images & médias","Redimensionnement correct, pas d'étirement, object-fit adapté, pas de recadrage destructeur"],["Formulaires","Champs entièrement visibles, labels lisibles, boutons accessibles, messages de validation visibles"],["Tableaux","Lisibles, scroll horizontal interne uniquement si nécessaire, la page ne casse pas"],["Footer","Colonnes empilées correctement, liens accessibles, aucun débordement"]]}},{"type":"heading","text":"4. Correctifs autorisés"},{"type":"list","items":["Refactoriser le CSS et améliorer les classes Tailwind (sm: md: lg: xl: 2xl:)","Ajuster les layouts Grid et Flexbox","Remplacer les largeurs fixes par des largeurs responsives","Remplacer les hauteurs fixes qui cassent la mise en page","Améliorer typographie et espacements responsives","Ajouter des containers max-width et une protection contre le débordement","Améliorer la navigation mobile et les layouts tablette"]},{"type":"callout","variant":"warning","title":"À éviter","text":"Largeurs fixes · hauteurs fixes qui cassent le layout · positionnement absolu qui casse sur mobile · overflow hidden utilisé pour masquer un vrai problème · scroll horizontal de page."},{"type":"heading","text":"5. Blocage de livraison"},{"type":"paragraph","text":"Livraison interdite s'il subsiste : scroll horizontal · layout cassé · éléments qui se chevauchent · texte illisible · boutons non cliquables · menu mobile cassé · formulaires inutilisables · images qui débordent · footer mal aligné · problèmes en mode sombre."},{"type":"heading","text":"6. Rapport final — par page"},{"type":"template","text":"Page : [Nom de la page]\nTailles testées : 1920 / 1440 / 1366 / 1280 / 1024 / 768 / 430 / 390 / 375 / 360\nProblèmes trouvés :\n- …\nCorrections appliquées :\n- …\nRésultat final : PASS"}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-dev-audit-responsive');

