INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-optimisation-images',
  'Optimiser les images d''un site pour la performance',
  'Compresser, convertir en WebP, générer les variantes desktop/tablette/mobile, appliquer lazy loading et fetchpriority, nettoyer les images inutilisées — sans toucher au design.',
