  $sop$[{"type":"callout","variant":"tip","title":"Objectif","text":"Site plus léger et plus rapide, sans changer le design, les textes ou la logique."},{"type":"heading","text":"Tâches — dans l'ordre"},{"type":"numbered","items":["Scanner /public et tous les sous-dossiers images","Identifier les JPG, JPEG, PNG trop lourds","Convertir chaque image en WebP","Créer une version optimisée par format : desktop max 1920px · tablette max 1200px · mobile max 768px","Remplacer dans le code toutes les anciennes images par les .webp","Ajouter loading=\"lazy\" sur toutes les images hors hero","Image hero : PAS de lazy loading, ajouter fetchpriority=\"high\" et decoding=\"async\"","Supprimer les images inutilisées uniquement si elles ne sont appelées nulle part","Vérifier le rendu sur mobile et desktop","Lancer npm run build et corriger les erreurs"]},{"type":"heading","text":"Exemple de balisage"},{"type":"code","text":"<!-- Hero : chargement prioritaire -->\n<img src=\"/img/hero.webp\" width=\"1920\" height=\"1080\"\n     fetchpriority=\"high\" decoding=\"async\" alt=\"…\" />\n\n<!-- Reste du site -->\n<img src=\"/img/service-1.webp\" width=\"800\" height=\"600\"\n     loading=\"lazy\" decoding=\"async\" alt=\"…\" />"},{"type":"callout","variant":"danger","title":"Interdits","text":"Ne pas changer le design · ne pas changer les textes · ne pas toucher à la logique du site. Le périmètre est strictement : optimisation des images et performance web."},{"type":"heading","text":"Résultat attendu"},{"type":"checklist","items":["Toutes les images en WebP","Poids total du projet réduit","Build sans erreur","Aucune image cassée sur mobile ni desktop","LCP amélioré (image hero prioritaire)"]}]$sop$::jsonb
