INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-dev-seo-wordpress',
  'Implémentation SEO technique et On-Page dans le code',
  'Stratégie de mots-clés, Search Console, sitemap, meta title et description, hiérarchie H1-H4, SEO technique, SEO local, validation et rapport de progression chiffré.',
  'dev',
  '["SEO","On-Page","Sitemap","Schema.org","SEO local"]'::jsonb,
  'Next Gital',
  8,
  false,
  $sop$[{"type":"callout","variant":"info","title":"Périmètre","text":"Implémenter concrètement les optimisations SEO directement dans le code du projet — pas seulement les recommander."},{"type":"heading","text":"1. Recherche et stratégie de mots-clés"},{"type":"list","items":["Analyser la structure actuelle du site et ses pages","Identifier les mots-clés principaux et secondaires de chaque page","Vérifier l'intention de recherche","Éviter le keyword stuffing","Placer les mots-clés naturellement dans titres, contenus, headings et métadonnées"]},{"type":"heading","text":"2. Google Search Console"},{"type":"list","items":["Vérifier l'indexabilité des pages","Vérifier les canonical URLs","Repérer les erreurs d'indexation","Préparer correctement le sitemap"]},{"type":"callout","variant":"warning","title":"Honnêteté","text":"Sans accès à Search Console, ne pas prétendre avoir effectué des vérifications impossibles : lister ce qui doit être vérifié manuellement."},{"type":"heading","text":"3. Sitemap XML"},{"type":"list","items":["Créer ou corriger le sitemap","Inclure uniquement les URL importantes et indexables","Exclure les pages inutiles, doublons, paramètres et pages non indexables","Rendre le sitemap accessible sur /sitemap.xml","Ajouter la référence au sitemap dans robots.txt"]},{"type":"heading","text":"4. Meta title et meta description"},{"type":"list","items":["Un <title> unique par page, avec le mot-clé principal, optimisé SEO ET CTR","Une meta description unique par page, expliquant le bénéfice de la page","Aucun titre ni description dupliqué entre les pages"]},{"type":"heading","text":"5. Structure H1 / H2 / H3 / H4"},{"type":"list","items":["Une hiérarchie logique et sémantique","Un H1 principal par page","Ne pas utiliser les headings uniquement pour le design","Les titres doivent décrire réellement le contenu"]},{"type":"heading","text":"6. SEO technique complémentaire"},{"type":"list","items":["robots.txt, canonical, URLs, indexabilité","Liens internes et ancres de liens","Images : attributs alt, poids, formats","Performance et Core Web Vitals","Responsive / mobile","Données structurées Schema.org, Open Graph, Twitter Cards","Balises HTML sémantiques, redirections, pages 404, contenu dupliqué, liens cassés, pagination"]},{"type":"heading","text":"7. SEO local"},{"type":"list","items":["Nom de l'entreprise, ville et zone géographique, services","Pages locales dédiées si pertinent","Données structurées LocalBusiness","NAP (nom, adresse, téléphone) cohérent","Lien vers la fiche Google Maps"]},{"type":"callout","variant":"danger","title":"Jamais de fausse information","text":"Ne jamais inventer une adresse, un horaire, un avis ou une certification."},{"type":"heading","text":"8. Validation finale"},{"type":"code","text":"npm run build\nnpm run lint\nnpx tsc --noEmit"},{"type":"checklist","items":["Routes fonctionnelles","Métadonnées présentes sur chaque page","Sitemap accessible","robots.txt correct","Canonical correct","Headings hiérarchisés","Images avec alt","Données structurées valides"]},{"type":"heading","text":"Rapport final obligatoire"},{"type":"template","text":"✅ TÂCHES TERMINÉES\n- …\n\n⚠️ TÂCHES PARTIELLEMENT RÉALISÉES\n- …\n\n❌ TÂCHES IMPOSSIBLES SANS ACCÈS EXTERNE\n- Google Search Console / Analytics / Business Profile\n\n📊 PROGRESSION SEO : XX %\n(expliquer précisément le calcul)\n\n🔴 RESTE À FAIRE\nPriorité 1 — Critique : …\nPriorité 2 — Importante : …\nPriorité 3 — Optimisation : …\n\n📁 FICHIERS MODIFIÉS\n- …\n\n🧪 TESTS EFFECTUÉS\n- commande → résultat"},{"type":"callout","variant":"danger","title":"Exigence","text":"Ne pas se contenter de dire « le SEO est optimisé ». Fournir un audit réel, des modifications réelles dans le code et un rapport précis."}]$sop$::jsonb
