INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-ai-claude-code-execute-mode',
  'Claude Code — mode EXECUTE et règles de travail Next Gital',
  'Le cadre de travail imposé à Claude Code : analyser avant de modifier, les 3 types de demandes (ajouter / corriger / supprimer), le workflow obligatoire et les interdictions git.',
  'ai',
  '["Claude Code","Méthode","Workflow","Git","IA"]'::jsonb,
  'Next Gital',
  6,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Mode EXECUTE","text":"Analyser d'abord le projet existant avant toute modification. Ne faire aucune supposition. Lire le code actuel, identifier l'architecture, les dépendances et les impacts avant d'agir."},{"type":"heading","text":"Les 3 types de demandes"},{"type":"heading2","text":"1. Ajouter une fonctionnalité"},{"type":"paragraph","text":"« Ajoute cette fonctionnalité : … »"},{"type":"list","items":["Implémenter la fonctionnalité complètement","Mettre à jour le frontend","Mettre à jour le backend","Mettre à jour la base de données si nécessaire","Mettre à jour les types et validations","Vérifier que tout fonctionne"]},{"type":"heading2","text":"2. Corriger un problème"},{"type":"paragraph","text":"« Cette fonctionnalité ne fonctionne pas : … »"},{"type":"list","items":["Reproduire le problème","Identifier la cause exacte","Corriger définitivement le bug","Vérifier les fonctionnalités liées","Tester après correction"]},{"type":"callout","variant":"warning","title":"Jamais d'hypothèse","text":"Ne jamais livrer une hypothèse. Trouver la vraie cause racine."},{"type":"heading2","text":"3. Supprimer une fonctionnalité"},{"type":"paragraph","text":"« Supprime cette partie : … »"},{"type":"list","items":["Supprimer l'interface","Supprimer la logique","Supprimer les routes / API inutilisées","Supprimer le code mort","Nettoyer les imports","Vérifier que le projet fonctionne toujours"]},{"type":"heading","text":"Workflow obligatoire"},{"type":"code","text":"# Avant toute modification\ngit pull\n\n# Après chaque modification\nnpm run build"},{"type":"paragraph","text":"Corriger toutes les erreurs, lancer ensuite l'application localement et tester la fonctionnalité modifiée."},{"type":"checklist","items":["Aucun problème responsive","Aucune erreur console","Aucune erreur API","Aucune erreur TypeScript","Aucune route cassée"]},{"type":"heading","text":"Interdictions"},{"type":"callout","variant":"danger","title":"Jamais automatiquement","text":"git commit · git push — sauf demande explicite écrite."},{"type":"heading","text":"Quand la demande est « git push »"},{"type":"numbered","items":["Vérifier le build","Vérifier les fonctionnalités","Corriger les erreurs éventuelles","Faire le commit","Pousser sur GitHub","Fournir un résumé des modifications"]},{"type":"callout","variant":"tip","title":"Principe final","text":"Ne jamais considérer qu'une fonctionnalité fonctionne. La tester, la vérifier, la corriger — puis seulement livrer le résultat."}]$sop$::jsonb
