rps minimal : {\"params\":{\"prompt\":\"…\",\"width_and_height\":\"1536x1024\"}}"]},{"type":"heading","text":"Confirmation avant de commencer"},{"type":"checklist","items":["Le projet localhost est accessible","Le fichier .env.local est correctement configuré",".env.local est bien dans .gitignore","L'environnement est prêt pour le développement"]}]$sop$::jsonb
