-- ── ng-ai-prompt-optimizer (ai) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-ai-prompt-optimizer',
  'Optimiseur de prompts — économiser les limites d''usage',
  'Transformer une demande vague en prompt précis et économe en tokens, dans une fenêtre séparée. Modèle FR/EN, règles de budget et installation en commande /prompt.',
  'ai',
  '["Prompt","Claude Code","Tokens","Productivité","IA"]'::jsonb,
  'Next Gital',
  5,
  true,
  $sop$[{"type":"callout","variant":"tip","title":"Principe","text":"Prend la demande d'un membre de l'équipe, aussi vague soit-elle, et produit un prompt précis prêt à coller dans Claude Code, avec la plus faible consommation de tokens possible."},{"type":"callout","variant":"warning","title":"Où l'utiliser","text":"Dans une conversation NEUVE et peu coûteuse (Claude.ai, ou une commande sur un petit modèle) — jamais dans la session Claude Code où l'on travaille. On ne reporte ensuite que le résultat."},{"type":"heading","text":"Règles strictes de l'optimiseur"},{"type":"numbered","items":["N'exécute jamais la tâche — produit uniquement le prompt","S'il manque une information critique (chemin de fichier, critère d'acceptation) : poser UNE seule question puis s'arrêter","Si la demande contient plusieurs tâches : ne produire que le prompt de la première, mentionner le reste sur une ligne « Plus tard : »","Ne jamais inventer un chemin de fichier — écrire une instruction de recherche bornée à la place","Maximum 150 mots pour le prompt produit","Préférer les patterns existants et les modifications minimales","Ne jamais ajouter de dépendance sauf demande explicite"]},{"type":"heading","text":"Modèle de sortie"},{"type":"template","text":"OBJECTIF : <une phrase : verbe + résultat mesurable>\n\nFICHIERS : <chemins exacts précédés de @. Si inconnus : « Commence par un Grep sur '<mot-clé>' ; ne lis pas plus de 3 fichiers »>\n\nMOTIF DE RÉFÉRENCE : <fichier ou fonction existante à imiter — ou « aucun »>\n\nCONTRAINTES :\n- <ce qui ne doit PAS changer : forme de l'API, schéma, dépendances, fichiers>\n\nCRITÈRE D'ACCEPTATION : <une commande qui doit passer, ou la sortie exacte attendue>\n\nSORTIE ATTENDUE : <diff uniquement | un seul fichier | N points>\n\nBUDGET : lire ≤ <N> fichiers · <aucun sous-agent | un sous-agent léger pour : …>"},{"type":"heading","text":"Règles de budget"},{"type":"table","table":{"headers":["Type de tâche","Budget"],"rows":[["Modification simple","≤ 3 fichiers, aucun sous-agent"],["Exploration","≤ 6 fichiers, un sous-agent léger"],["Architecture","Recommander le Plan mode d'abord, pas l'exécution directe"]]}},{"type":"heading","text":"Exemple complet"},{"type":"paragraph","text":"Entrée : « Le panier se vide quand l'utilisateur recharge la page, corrige ça »"},{"type":"template","text":"OBJECTIF : Conserver le contenu du panier après un rechargement de page.\n\nFICHIERS : Commence par un Grep sur « cart » dans src/ ; ne lis pas plus de 3 fichiers.\n\nMOTIF DE RÉFÉRENCE : reprendre l'approche de persistance déjà utilisée par le store de session d'authentification.\n\nCONTRAINTES :\n- Ne pas changer le schéma des articles du panier\n- Aucune nouvelle dépendance\n- Côté client uniquement, aucune modification d'API\n\nCRITÈRE D'ACCEPTATION : Ajouter un article → recharger → l'article est toujours présent. `npm test -- cart` passe.\n\nSORTIE ATTENDUE : diff uniquement, sans explication.\n\nBUDGET : lire ≤ 3 fichiers · aucun sous-agent"},{"type":"callout","variant":"success","title":"Gain mesuré","text":"≈ 80 000 tokens → ≈ 6 000 tokens sur cet exemple."},{"type":"heading","text":"En faire une commande Claude Code"},{"type":"paragraph","text":"Créer .claude/commands/prompt.md dans le projet (ou ~/.claude/commands/prompt.md pour tous les projets) :"},{"type":"code","text":"---\ndescription: Transforme une demande vague en prompt précis et économe en tokens\nmodel: haiku\n---\n\nRole: prompt optimizer. Turn the request below into a specific, token-cheap prompt.\nNever execute it. Output only the template. Max 150 words.\nIf a critical detail is missing, ask ONE question and stop.\n\nTemplate:\nGOAL / FILES / REFERENCE PATTERN / CONSTRAINTS / ACCEPTANCE / OUTPUT / BUDGET\n\nRequest: $ARGUMENTS"},{"type":"paragraph","text":"Utilisation : /prompt il faut corriger le panier qui se vide tout seul"},{"type":"callout","variant":"danger","title":"Règle d'équipe","text":"Aucune demande n'est envoyée à Claude Code sans être passée par l'optimiseur. Une minute de reformulation économise une heure de limite hebdomadaire."}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-ai-prompt-optimizer');

