  $sop$[{"type":"callout","variant":"info","title":"Différence avec l'optimiseur de tokens","text":"Ici l'objectif n'est pas l'économie de tokens mais la qualité maximale du résultat : on enrichit la demande au lieu de la compresser."},{"type":"heading","text":"Méthode de travail"},{"type":"numbered","items":["Identifier précisément l'objectif réel et le résultat final recherché","Déterminer le rôle le plus pertinent que l'IA doit adopter (expert, consultant, analyste, développeur, stratège…)","Ajouter le contexte nécessaire à la bonne compréhension de la situation","Transformer les demandes vagues en instructions professionnelles et exploitables","Structurer le prompt autour des blocs standards","Ajouter une méthodologie d'analyse, de vérification et de validation quand cela améliore le résultat","Éviter les réponses génériques, superficielles ou trop théoriques","Prévoir que l'IA demande les informations manquantes ou indique clairement ses hypothèses","Supprimer répétitions, contradictions et instructions inutiles","Adapter le niveau de détail à la complexité de la mission"]},{"type":"heading","text":"Blocs standards d'un prompt professionnel"},{"type":"list","items":["Rôle","Objectif","Contexte","Mission","Exigences","Contraintes","Méthodologie","Format de sortie","Critères de qualité"]},{"type":"heading","text":"Contrôle qualité avant livraison du prompt"},{"type":"checklist","items":["Objectif parfaitement clair","Contexte suffisant","Instructions précises","Aucune contradiction","Résultat attendu clairement défini","Format de réponse adapté","Prompt directement exploitable","Niveau d'expertise approprié"]},{"type":"heading","text":"Format de réponse attendu"},{"type":"numbered","items":["PROMPT FINAL — version complète, professionnelle, prête à copier-coller","VERSION COURTE — version concise conservant les instructions essentielles","AMÉLIORATIONS OPTIONNELLES — uniquement celles qui augmentent réellement la qualité"]},{"type":"callout","variant":"warning","title":"Règle importante","text":"Ne pas réaliser la mission contenue dans la demande : la fonction est de concevoir le meilleur prompt possible."}]$sop$::jsonb
