  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-ai-reformulation-prompt-pro');

-- ── ng-ai-diagnostic-probleme (ai) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-ai-diagnostic-probleme',
  'Diagnostiquer et corriger un problème — méthode cause racine',
  'À partir d''une phrase ou d''une capture d''écran : analyser, chercher la cause racine dans tout le projet, corriger le minimum nécessaire, tester et confirmer. Format de réponse imposé.',
  'ai',
  '["Debug","Diagnostic","Cause racine","Support","IA"]'::jsonb,
  'Next Gital',
  4,
  true,
  $sop$[{"type":"callout","variant":"danger","title":"Interdit","text":"Ne pas se contenter de dire ce qui pourrait être le problème. La séquence attendue est : ANALYSER → TROUVER LA CAUSE → CORRIGER → TESTER → CONFIRMER."},{"type":"heading","text":"Règles de diagnostic"},{"type":"numbered","items":["Analyser d'abord le projet et le code existant","Chercher toutes les causes possibles liées au problème","Identifier la cause racine réelle, pas seulement le symptôme","Localiser exactement : fichier, fonction, composant, configuration, API, base de données, dépendance, serveur, environnement","Vérifier l'hypothèse dans le code avant de conclure","Corriger directement une fois la cause confirmée","Ne modifier que ce qui est nécessaire","Ne casser aucune fonctionnalité existante","Effectuer les tests ou vérifications nécessaires après correction","Si une première solution ne fonctionne pas, poursuivre le diagnostic"]},{"type":"callout","variant":"warning","title":"Autonomie","text":"Ne pas demander où chercher : chercher soi-même dans tout le projet."},{"type":"heading","text":"À partir d'une capture d'écran"},{"type":"numbered","items":["Diagnostic — erreurs, anomalies ou incohérences détectées","Causes probables — côté code, configuration, réseau…","Solutions concrètes — les étapes exactes, dans l'ordre","Ce qu'il faut vérifier — les informations manquantes à fournir"]},{"type":"heading","text":"Format de réponse imposé"},{"type":"template","text":"Problème identifié :\n…\n\nCause racine :\n…\n\nFichier(s) modifié(s) :\n…\n\nCorrection effectuée :\n…\n\nTests effectués :\n…\n\nRésultat :\n…"},{"type":"callout","variant":"tip","title":"Version autonome","text":"« Corrige complètement sans me poser de questions. Corrige la cause racine proprement, sans introduire de nouvelles erreurs ailleurs. Après le correctif, vérifie que tout fonctionne de bout en bout (app, tests, vérifications), puis fais un compte rendu de ce qui n'allait pas et de la correction. »"}]$sop$::jsonb
