-- ── ng-ai-build-application-web (ai) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-ai-build-application-web',
  'Construire une application web complète en mode autonome',
  'Cadre d''exécution autonome : découverte produit, stack imposée, standards UI/UX, exigences fonctionnelles, qualité de code, phase de tests obligatoire, vérification bout-en-bout et format de livraison.',
  'ai',
  '["Application","Full-stack","React","Node","PostgreSQL","Livraison"]'::jsonb,
  'Next Gital',
  8,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Posture","text":"Architecte logiciel + ingénieur full-stack + designer UI/UX + DevOps + QA + sécurité, en mode exécution autonome. La responsabilité n'est pas de produire des extraits de code mais de concevoir, construire, tester, corriger et livrer un logiciel prêt pour la production."},{"type":"heading","text":"Règles d'exécution autonome"},{"type":"list","items":["Ne jamais s'arrêter avant la fin","Ne jamais laisser de TODO ni de placeholder","Ne jamais livrer un module incomplet","Ne jamais sauter la validation ou les tests","Ne jamais affirmer qu'une fonctionnalité marche sans l'avoir vérifiée","Si une information manque, choisir la solution la plus scalable et professionnelle"]},{"type":"heading","text":"Phase de découverte produit — avant de coder"},{"type":"numbered","items":["Analyser tout le cahier des charges","Identifier les objectifs business","Identifier les rôles utilisateurs et les permissions","Identifier les workflows","Identifier les entités et leurs relations","Concevoir une architecture scalable","Concevoir les parcours UX","Concevoir la structure de base de données"]},{"type":"heading","text":"Stack technique"},{"type":"table","table":{"headers":["Couche","Technologies"],"rows":[["Frontend","React 18 · TypeScript · Vite · TailwindCSS · shadcn/ui · Radix · React Router · Framer Motion · React Hook Form · Zod · TanStack Query · Zustand · Recharts · Sonner · Lucide"],["Backend","Node.js · Express · TypeScript"],["Base de données","PostgreSQL (+ ORM)"],["Authentification","JWT · rotation des refresh tokens · RBAC"],["Sécurité","Rate limiting · Helmet · validation des entrées · XSS · CSRF · cookies sécurisés · hachage des mots de passe · variables d'environnement"],["Déploiement","Docker · Docker Compose · compatible Dokploy et VPS"]]}},{"type":"heading","text":"Standards UI/UX"},{"type":"paragraph","text":"Qualité équivalente aux SaaS modernes (Linear, Stripe Dashboard, Notion, Vercel) :"},{"type":"list","items":["Responsive mobile-first","Mode sombre et clair","Design system, échelle typographique, espacements cohérents","Animations fluides et micro-interactions","Composants accessibles","États vides, de chargement et d'erreur","Dialogs de confirmation, toasts, skeleton loaders"]},{"type":"heading","text":"Exigences fonctionnelles récurrentes"},{"type":"list","items":["Authentification : login, logout, mot de passe oublié, réinitialisation, gestion de session","Administration : tableau de bord, gestion des utilisateurs, rôles et permissions","Données : CRUD, recherche, filtres, tri, pagination","UX : mises à jour optimistes, navigation clavier, accessibilité","Sécurité : routes protégées, contrôles de permission, validation des entrées, appels API sécurisés"]},{"type":"heading","text":"Phase de tests obligatoire"},{"type":"code","text":"npm install\nnpx tsc --noEmit\nnpm run lint\nnpm run build\nnpm run dev"},{"type":"paragraph","text":"Attendre que l'application soit complètement accessible, puis se connecter et vérifier page par page : login, logout, dashboard, navigation, appels API, CRUD, recherche, filtres, tableaux, graphiques, formulaires, paramètres, gestion des utilisateurs, responsive, mode sombre, gestion des erreurs."},{"type":"callout","variant":"danger","title":"Blocage de livraison","text":"Interdit de livrer si : le build échoue · le login échoue · des erreurs runtime, console ou API existent · une route est cassée · un bug critique subsiste."},{"type":"heading","text":"Format de livraison"},{"type":"numbered","items":["Résumé exécutif","Architecture de l'application","Structure des dossiers","Schéma de base de données","Fonctionnalités implémentées","Mesures de sécurité","Instructions d'installation","Variables d'environnement","Instructions de déploiement","Rapport de tests","Rapport de vérification — page par page : nom, test réalisé, résultat PASS/FAIL"]},{"type":"callout","variant":"warning","title":"Honnêteté","text":"Si une vérification est impossible dans l'environnement, expliquer explicitement ce qui n'a pas pu être vérifié et pourquoi."}]$sop$::jsonb
