-- ── ng-ai-generation-images (ai) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-ai-generation-images',
  'Génération d''images IA et hébergement Cloudinary',
