  $sop$[{"type":"callout","variant":"tip","title":"Objectif du site","text":"Présenter le professionnel ou l'établissement, ses spécialités et prestations, renforcer la confiance, faciliter la prise de rendez-vous et donner rapidement les informations recherchées par les patients."},{"type":"callout","variant":"danger","title":"Ne jamais inventer","text":"Aucun diplôme, chiffre, témoignage, certification, tarif ou information médicale ne doit être inventé. Si une information essentielle manque, la demander AVANT de concevoir."},{"type":"heading","text":"Direction artistique"},{"type":"paragraph","text":"Inspirer : confiance + expertise + modernité + propreté + sérénité + proximité humaine."},{"type":"table","table":{"headers":["À éviter","À privilégier"],"rows":[["Aspect froid et hospitalier","Espaces blancs généreux"],["Interfaces surchargées","Excellente hiérarchie typographique"],["Couleurs agressives","Grandes photographies professionnelles"],["Animations inutiles","Sections aérées, cartes élégantes"],["Clichés médicaux et banques d'images artificielles","Micro-interactions discrètes, CTA parfaitement visibles"]]}},{"type":"heading","text":"Arborescence — sélectionner ce qui a une vraie utilité"},{"type":"list","items":["Accueil","À propos / Le médecin","Spécialités","Services / Prestations","Pages individuelles pour les principales prestations","Informations patients","FAQ","Contact","Prendre rendez-vous"]},{"type":"callout","variant":"warning","title":"Pas de page inutile","text":"Ne pas créer automatiquement toutes ces pages : ne garder que celles qui ont une utilité UX, commerciale ou SEO."},{"type":"heading","text":"Page d'accueil — section par section"},{"type":"numbered","items":["Header — logo, navigation claire, téléphone, CTA de rendez-vous","Hero — spécialité, nom, localisation, proposition de valeur, CTA principal et secondaire, photo professionnelle","Réassurance — diplômes, expérience, expertise, certifications","Présentation — courte présentation + lien vers la page complète","Services / spécialités — cartes scannables : icône, nom, courte description, « En savoir plus »","Pourquoi choisir ce professionnel — uniquement de vrais éléments différenciants","Parcours patient — prise de rendez-vous, consultation, suivi","Témoignages — structure prévue si de vrais avis existent","FAQ — questions réellement utiles aux patients","Contact / rendez-vous — adresse, téléphone, WhatsApp, horaires, carte, CTA","Footer — coordonnées, navigation secondaire, réseaux, informations légales"]},{"type":"paragraph","text":"Pour chaque section, préciser : objectif UX · structure visuelle · contenu à afficher · CTA · éléments graphiques recommandés."},{"type":"heading","text":"UX mobile — approche mobile first"},{"type":"list","items":["Navigation mobile simple","CTA facilement accessible, boutons suffisamment grands","Numéros de téléphone cliquables, WhatsApp si disponible","Formulaires courts, sections faciles à parcourir","Typographie lisible, images optimisées","Barre CTA mobile fixe (Appeler | WhatsApp | Rendez-vous) uniquement si elle améliore réellement l'expérience"]},{"type":"heading","text":"Design system"},{"type":"list","items":["Palette complète avec rôle de chaque couleur","Typographie : polices titres et corps, tailles H1/H2/H3, interlignage","Boutons : primary, secondary, hover, disabled","Composants : cartes, formulaires, champs, badges, témoignages, accordéons FAQ, icônes, navigation, footer","Espacement : marges, paddings, espaces entre sections, largeur max, border radius, ombres"]},{"type":"heading","text":"Accessibilité"},{"type":"checklist","items":["Contraste texte/fond","Taille des textes","Navigation claire","États hover / focus","Boutons identifiables","Formulaires compréhensibles","Hiérarchie H1/H2/H3","Usage raisonnable des animations"]},{"type":"heading","text":"Conversion"},{"type":"paragraph","text":"CTA principal unique (ex : prendre rendez-vous), CTA secondaires appropriés (appeler, WhatsApp, voir les prestations, obtenir l'itinéraire). Parcours : découverte → confiance → compréhension des services → réassurance → prise de contact."}]$sop$::jsonb
FROM public.tenants t
