  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-design-ux-site-medical');

-- ── ng-design-direction-artistique-2040 (designer) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-design-direction-artistique-2040',
  'Direction artistique Next Gital — refonte premium « Future 2040 »',
  'Le standard de refonte Next Gital en 14 étapes : analyser avant de modifier, respecter le contenu et la marque, design system, motion, 3D, rythme visuel, mobile first, performance et tests finaux.',
  'designer',
  '["Direction artistique","Refonte","Motion","3D","Next Gital","Standard"]'::jsonb,
  'Next Gital',
  10,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Posture","text":"Senior UI/UX Designer, Creative Director et Creative Developer Next Gital — niveau d'exigence d'une agence digitale internationale."},{"type":"callout","variant":"warning","title":"Le futurisme reste subtil","text":"Le résultat ne doit jamais être compliqué, froid, illisible, lent, artificiel, excessivement animé ni ressembler à un jeu vidéo. Priorité : UX → confiance → conversion → identité de marque → design → motion → 3D."},{"type":"heading","text":"Règle n°1 — analyser avant de modifier"},{"type":"paragraph","text":"Ne pas commencer à coder. Analyser d'abord : structure, pages, navigation, contenu, identité visuelle, logo, couleurs, typographie, images, services, CTA, formulaires, responsive, SEO, performance, parcours utilisateur, points faibles et forts, éléments à conserver."},{"type":"paragraph","text":"Comprendre : QUI est le client ? QUE vend-il ? À QUI s'adresse-t-il ? QUEL est l'objectif du site ? QUELLE action doit effectuer le visiteur ?"},{"type":"heading","text":"Ne pas détruire le contenu existant"},{"type":"callout","variant":"danger","title":"Interdits","text":"Ne pas supprimer arbitrairement services, informations, coordonnées, témoignages, textes importants, pages, informations légales ou données SEO. Ne jamais inventer de fausses informations ni remplacer du contenu réel par du lorem ipsum."},{"type":"paragraph","text":"Le contenu existant doit être conservé + organisé + amélioré si nécessaire + mieux présenté. Le design sert le contenu."},{"type":"heading","text":"Identité de marque"},{"type":"paragraph","text":"Analyser le logo et l'identité existante. Le nouveau design respecte le logo, les couleurs principales, les valeurs, le secteur, la clientèle et le positionnement. Ne pas imposer la même palette à tous les clients : chaque site conserve sa personnalité."},{"type":"heading","text":"Design system à produire"},{"type":"list","items":["Couleurs (primaire, secondaire, accent, backgrounds, textes, bordures, hover, success/error)","Typographie et hiérarchie H1 → caption","Spacing, border radius, shadows","Boutons, cards, forms, icons, badges","Navigation, CTA, animations, breakpoints"]},{"type":"heading","text":"Hero"},{"type":"paragraph","text":"Le hero répond à 4 questions : QUI ? QUOI ? POUR QUI ? QUE FAIRE ? Il contient : badge ou catégorie, H1, proposition de valeur, description courte, CTA principal, CTA secondaire si nécessaire, élément visuel fort."},{"type":"callout","variant":"warning","title":"Le visuel doit raconter quelque chose","text":"Ne pas ajouter un élément uniquement parce qu'il est « cool »."},{"type":"heading","text":"Motion, 3D et effets"},{"type":"list","items":["Motion : fade, reveal, slide, scale, parallax, blur reveal, floating, text reveal, hover, magnetic, scroll animation","Règle : « L'utilisateur doit ressentir l'animation avant de la remarquer »","3D : uniquement si elle améliore réellement l'expérience — chaque élément 3D doit avoir une fonction visuelle ou narrative","Particles : très subtiles, adaptées au secteur (tech, science, médical, finance, architecture)","Luxury UI : 10-20 % maximum — glassmorphism subtil, surfaces translucides, bordures fines, profondeur, gradients subtils"]},{"type":"callout","variant":"danger","title":"Ne pas surdesigner","text":"Ne jamais utiliser simultanément partout : particles + 3D + glassmorphism + gradients + animations + shadows + vidéos. LESS BUT BETTER."},{"type":"heading","text":"Rythme visuel"},{"type":"code","text":"Section immersive\n→ Section minimaliste\n→ Section éditoriale\n→ Section interactive\n→ Section humaine\n→ Section premium\n→ CTA"},{"type":"paragraph","text":"Toutes les sections ne doivent pas avoir le même style : le contraste crée le sentiment de qualité."},{"type":"heading","text":"Règle 70 / 20 / 10"},{"type":"list","items":["70 % — clarté + contenu + espaces","20 % — design premium + interactions","10 % — wow / 3D / motion / expérience"]},{"type":"heading","text":"Mobile first et performance"},{"type":"paragraph","text":"Tester 375 / 390 / 430 / 768 / 1024 / 1280 / 1440 / 1920 px. Optimiser : images (WebP, AVIF), lazy loading, vidéo, 3D, JavaScript, CSS, fonts, code splitting. Sur appareils faibles : réduire automatiquement les effets lourds. Respecter prefers-reduced-motion."},{"type":"heading","text":"SEO — ne pas le sacrifier au design"},{"type":"list","items":["H1, H2, H3","title, meta description","URLs et maillage interne","Schema et données locales","Alt des images","Performance et Core Web Vitals"]},{"type":"heading","text":"Ordre d'exécution — 14 étapes"},{"type":"numbered","items":["Auditer le site existant","Comprendre la marque et le secteur","Identifier l'objectif commercial principal","Identifier les problèmes UX/UI","Définir le nouveau design system","Définir la direction artistique","Définir les éléments 3D / vidéo / IA nécessaires","Refondre le hero","Refondre les sections principales","Améliorer les CTA et la conversion","Optimiser mobile","Optimiser la performance","Vérifier le SEO","Tester l'ensemble du site"]},{"type":"heading","text":"Tests finaux"},{"type":"heading2","text":"Test des 5 secondes"},{"type":"paragraph","text":"Après chargement du hero, l'utilisateur doit comprendre : qui est la marque, ce qu'elle propose, pourquoi elle est différente, et ce qu'il doit faire. Sinon → modifier le hero."},{"type":"heading2","text":"Test de conversion"},{"type":"checklist","items":["Le CTA principal est évident","L'utilisateur sait comment contacter l'entreprise","Il existe une preuve de confiance","Le parcours est simple","Le site répond aux objections principales"]},{"type":"heading2","text":"Test mobile (375 / 390 / 430 px)"},{"type":"checklist","items":["Aucun overflow horizontal","Aucun texte coupé","Aucun bouton trop petit","Aucune animation gênante","Aucun élément inaccessible","Aucun formulaire difficile"]},{"type":"callout","variant":"success","title":"Standard final","text":"Le résultat doit donner deux impressions à la fois : « ce site est clairement plus avancé que les sites classiques du marché » ET « je comprends immédiatement l'entreprise et je sais quoi faire »."}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-design-direction-artistique-2040');

-- ── ng-design-site-one-file-premium (designer) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-design-site-one-file-premium',
  'Produire un site premium en un seul fichier (HTML/CSS/JS)',
  'Livrable one-file niveau Awwwards : structure des sections, animations GSAP/Lenis, effets obligatoires, responsive fluide, contraintes d''assets et lancement du serveur local.',
  'designer',
  '["HTML","GSAP","Animation","Awwwards","Landing page"]'::jsonb,
  'Next Gital',
  6,
  false,
  $sop$[{"type":"callout","variant":"info","title":"Livrable","text":"UN SEUL fichier HTML complet : CSS dans <style> avec variables dans :root, JS dans <script> en bas, code commenté, HTML sémantique et accessible."},{"type":"heading","text":"Règles absolues sur les assets"},{"type":"list","items":["Utiliser exactement les couleurs et le fond fournis, sans les modifier","Utiliser uniquement l'image hero fournie — aucune image externe","Pour les autres sections : CSS, SVG, gradients (pas d'images stock)"]},{"type":"heading","text":"Structure du site"},{"type":"numbered","items":["Navbar sticky avec blur au scroll","Hero full-width 100vh — texte à gauche (titre XXL + description + 2 CTA), image avec effet Ken Burns + parallax, overlay dégradé","Section à propos (bento layout)","Section services (cards glassmorphism)","Section galerie","Section témoignages (marquee infini)","Section contact (localisation + contact cliquable)","Footer minimaliste"]},{"type":"paragraph","text":"CTA hero : bouton 1 → WhatsApp ou tel: · bouton 2 → scroll smooth vers la section suivante."},{"type":"heading","text":"Librairies (CDN)"},{"type":"list","items":["GSAP + ScrollTrigger","Lenis (smooth scroll)"]},{"type":"heading","text":"Effets obligatoires"},{"type":"checklist","items":["Smooth scroll global","Curseur personnalisé qui grossit au hover","Split text animé sur le titre hero","Reveal au scroll (fade + slide + stagger)","Parallax multi-couches","Ken Burns infini sur l'image hero","Magnetic buttons","Marquee infini pour les témoignages","Compteurs animés","Noise texture overlay (grain)","Loader élégant au chargement","Hover tilt 3D sur les cards","Underline animé sur les liens"]},{"type":"heading","text":"Responsive et performance"},{"type":"list","items":["Mobile-first","Breakpoints : 480 / 768 / 1024 / 1440 px","Typographie fluide avec clamp()","prefers-reduced-motion respecté","Objectif Lighthouse 90+","Animations à 60 fps"]},{"type":"heading","text":"Livraison"},{"type":"code","text":"📁 Structure du projet :\n   /nom-du-site\n     ├── index.html\n     ├── style.css   (si séparé)\n     └── script.js   (si séparé)\n\n💻 Commande de lancement :\n   npx serve .        # ou python3 -m http.server 3000\n\n🔗 Lien de prévisualisation :\n   http://localhost:XXXX"}]$sop$::jsonb
FROM public.tenants t
WHERE EXISTS (SELECT 1 FROM public.sops b WHERE b.tenant_id = t.id AND b.slug LIKE 'ng-%')
  AND NOT EXISTS (SELECT 1 FROM public.sops WHERE tenant_id = t.id AND slug = 'ng-design-site-one-file-premium');

