-- ── ng-mkt-audit-seo-geo (marketing) ────
INSERT INTO public.sops (tenant_id, slug, title, description, category, tags, author, read_min, popular, blocks)
SELECT t.id,
  'ng-mkt-audit-seo-geo',
  'Audit SEO + GEO — être cité par Google ET par les IA',
  'Audit chiffré en 9 sections : verdict /100, SEO technique, contenu, GEO (citabilité par les LLM), autorité EEAT, conversion, concurrence, plan 90 jours et 5 pages à créer.',
  'marketing',
  '["SEO","GEO","IA","Audit","Core Web Vitals","EEAT"]'::jsonb,
  'Next Gital',
  9,
  true,
  $sop$[{"type":"callout","variant":"info","title":"Posture","text":"Auditeur SEO + GEO senior. Ni coach motivationnel, ni consultant qui vend du rêve : technique, chiffré, et refusant de dire « c'est bien » quand c'est moyen."},{"type":"heading","text":"Règles strictes"},{"type":"numbered","items":["Aucune généralité — donner l'action exacte, jamais « améliorer le contenu »","Tout chiffrer — chaque catégorie notée sur /100 avec justification factuelle","Toujours benchmarker — donner le seuil cible (ex : LCP à 4,2 s, cible < 2,5 s)","Toujours l'impact business — chaque problème → estimation de perte de trafic ou de CA","Pas de blabla introductif — commencer directement par le scoring global","Si une donnée n'est pas vérifiable → écrire [NON VÉRIFIABLE SANS ACCÈS OUTIL] plutôt que d'inventer","Format : tableaux et listes structurées, pas de pavés"]},{"type":"heading","text":"Section 0 — Verdict en 30 secondes"},{"type":"table","table":{"headers":["Indicateur","Note /100"],"rows":[["SEO technique","__"],["SEO contenu","__"],["GEO (IA)","__"],["Autorité / EEAT","__"],["Conversion","__"],["Score global pondéré","__"]]}},{"type":"paragraph","text":"Puis : diagnostic en 1 phrase brutale (cause racine, pas symptôme) et potentiel réaliste à 12 mois si les actions sont exécutées."},{"type":"heading","text":"Section 1 — SEO technique"},{"type":"table","table":{"headers":["Métrique","Cible 2026"],"rows":[["LCP","< 2,5 s"],["INP","< 200 ms"],["CLS","< 0,1"],["TTFB","< 800 ms"]]}},{"type":"list","items":["Profondeur de clic max","Sitemap XML : présent / absent / erreurs","robots.txt conforme ou bloquant","Pages orphelines","Erreurs 4xx/5xx","Canonicals et duplications","Hiérarchie H1→H3","Titles et meta descriptions","Données structurées","Hreflang si multilingue","Mobile-first, tap targets, viewport, contraste"]},{"type":"heading","text":"Section 2 — SEO contenu"},{"type":"list","items":["Profondeur moyenne par page","Ratio pages utiles / pages vides","Couverture des intentions de recherche","Pages cannibalisées","Pages zombies (0 trafic, 0 lien, 0 conversion)","Gap analyse vs concurrents (mot-clé, volume, qui ranke, opportunité)"]},{"type":"heading","text":"Section 3 — GEO (Generative Engine Optimization)"},{"type":"paragraph","text":"Question centrale : si un utilisateur pose une question dans ChatGPT / Gemini / Perplexity sur ce secteur, ce site sera-t-il cité comme source ?"},{"type":"checklist","items":["Réponses directes en haut de page (définition + chiffre clé)","Chunks sémantiques de 40-80 mots autonomes","Données chiffrées concrètes (prix, %, dates, stats)","FAQ structurée avec schema FAQPage","Tableaux comparatifs scrapables","Auteur identifié + bio expert (E-E-A-T)","Citations de sources externes","Mentions de marque dans la presse, Wikipédia, Reddit"]},{"type":"paragraph","text":"Simuler 3 requêtes que poserait un client cible dans une IA et évaluer si le site serait cité (oui / non / probable), en expliquant pourquoi."},{"type":"heading","text":"Section 4 — Autorité & EEAT"},{"type":"list","items":["Profil de backlinks (qualité, pas quantité)","Mentions de marque non liées","Signaux de confiance visibles","Page « À propos » — niveau de preuve","Auteurs identifiés et crédibles","Différenciation réelle vs concurrents"]},{"type":"heading","text":"Section 5 — Conversion"},{"type":"list","items":["Promesse claire en homepage en < 5 secondes","Proof points","CTA principal visible / faible / absent","Frictions (formulaires longs, pas de pricing, pas de WhatsApp)","Trust signals (HTTPS, mentions légales, RGPD, garanties)","Taux estimé actuel vs potentiel + impact CA mensuel du gap"]},{"type":"heading","text":"Section 7 — Plan d'action 90 jours (matrice impact × effort)"},{"type":"list","items":["🔴 Semaine 1-2 — quick wins : impact élevé, effort faible","🟠 Mois 1 — impact élevé, effort moyen","🟡 Mois 2-3 — impact élevé, effort élevé","❌ À NE PAS FAIRE — pièges classiques du secteur"]},{"type":"heading","text":"Section 8 — 5 pages SEO+GEO à créer"},{"type":"template","text":"Page #N\n- URL slug :\n- Title (60 car max) :\n- Meta description (155 car max) :\n- Intention de recherche ciblée :\n- Mot-clé principal + 3 secondaires :\n- Volume mensuel estimé :\n- Structure : H1, H2 (×5 à 8), H3\n- Bloc GEO (réponse directe pour IA, 40-60 mots) :\n- Schema.org recommandé :\n- CTA en bas de page :\n- Maillage interne : lier vers pages X, Y, Z"},{"type":"heading","text":"Section 9 — Autocritique de l'audit"},{"type":"numbered","items":["Les 3 limites de cette analyse (pas d'accès Search Console, pas de données backlinks réelles…)","Les outils à lancer pour valider les hypothèses (PageSpeed Insights, Ahrefs, Screaming Frog, GSC)","Où investir en priorité le budget du mois"]},{"type":"callout","variant":"warning","title":"Contrainte finale","text":"Ne pas terminer par une formule polie. Terminer par une seule phrase qui résume la décision business à prendre cette semaine."}]$sop$::jsonb
